window.READER_DATA={"title": "Sharh Bay3a", "slug": "sharh-bay3a", "pages": [{"n": 1, "paras": ["البيعة شرح رسالة (التعاليم) للإمام الشهيد حسن البنا", "شرح عبد المنعم أحمد تعليب", "القاهرة مطبعة دار الكتاب العربي"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0001.png"}, {"n": 2, "paras": ["شباب النادي الشبابي"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0002.png"}, {"n": 3, "paras": ["بِسْمِ اللَّهِ الرَّحْمَنِ الرَّحِيمِ", "« إِنَّ الَّذِينَ يُبَايِعُونَكَ إِنَّمَا يُبَايِعُونَ اللَّهَ يَدُ اللَّهِ فَوْقَ أَيْدِيهِمْ فَمَنْ نَكَثَ فَإِنَّمَا يَنْكُثُ عَلَى نَفْسِهِ وَمَنْ أَوْفَى بِمَا عَاهَدَ عَلَيْهُ اللَّهَ فَسَيُؤْتِيهِ أَجْرًا عَظِيمًا ». « قرآن كريم »"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0003.png"}, {"n": 4, "paras": ["تمهيد", "كل من في الوجود يطلب ربحاً . وخير الربح أدومه . لهذا فأنا أعرض هذه البيعة على الناس جميعاً لعلهم يشترون فيربحون . فمن قبلها ودخل فيها ربح ثواب الدنيا وحسن ثواب الآخرة ومن لم يشتر فلن يضر إلا نفسه لأن البضاعة لن تبور ، وصاحبها غنى له خزائن السموات والارض ، ومن تبايع ثم غدر فقد خسر خسراناً مبيناً .", "أيها الأخ الكريم : أتدري ما البضاعة ؟ وما ثمنها ؟ ومن صاحبها ؟ البضاعة الجنة ، وصاحبها مولاك والثمن نفسك وما ملكت يداك ، فهل تحب أن تدخل مع الله في تجارة يشترى منك وتبيع له وهو ضامن لك الربح ؟ إن أحببت هذا فتعال معى نتدارس شروط البيع على تعاليم إمامنا الشهيد رضوان الله تعالى عليه - وسأتناولها إن شاء الله"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0004.png"}, {"n": 5, "paras": ["بأسلوب يسير حتى تكون واضحة مفهومة - فإن رأيت أنك تستطيع الوفاء بها فلنضع أيدينا في يد مرشدنا أيده الله ونفع به .", "وادع معي بدعاء سيد المرسلين وقائد المجاهدين ( اللهم إنا نسألك عيش السعداء وموت الشهداء والفوز في القضاء والنصر على الاعداء ) اللهم آمين .", "عبد المنعم احمد"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0005.png"}, {"n": 6, "paras": ["بسم الله الرحمن الرحيم", "والحمد لله والصلاة والسلام على إمام المتقين وقائد المجاهدين سيدنا محمد النبي الأمين وعلى آله وصحبه ومن تبع هداهم إلى يوم الدين . أما بعد :", "فهذه رسالتي إلى الاخوان المجاهدين من الاخوان المسلمين الذين آمنوا بسمو دعوتهم وقدسية فكرتهم وعزموا صادقين على ان يعيشوا بها او يموتوا في سبيلها :", "رسالة التعاليم هذه كما يظهر من اسمها أوامر وتعليمات من قائد الدعوة الى الذين قبلوا الجندية فيها ، مؤمنين بأنهم حزب الله يحملون نوره ويهدون لدينه ويحرسون شريعة رسوله فهم بهذا ربانيون ( آمنوا بسمو دعوتهم وقدسية فكرتهم )"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0006.png"}, {"n": 7, "paras": ["إلى هؤلاء الاخوان فقط اوجه هذه الكلمات الموجزة وهي ليست دروساً تحفظ لكنها تعليمات تنفذ . فالى العمل ايها الأخوة الصادقون ( وسيرى الله عملكم ورسوله والمؤمنون وستردون إلى عالم الغيب والشهادة فينبئكم بما كنتم تعملون ) .", "وكل مجند لا بد أن يقسم يمين الولاء . و ولاؤك لله لا يكون إلا بعهد بينك وبينه أن تدافع عن الاسلام حق لا تكون فتنة ويكون الدين كله لله ، أو تموت دون ذلك . وبهذا تكون من ورثة دعوة رسول الله . الذين اعتزوا بها ( وعزموا صادقين على أن يعيشوا بها أو يموتوا في سبيلها ) .", "والجنود وحدهم هم المدعوون لهذه البيعة . وسترى من إيجازها ووضوح ألفاظها أنها الى الأوامر العسكرية أقرب منها الى الأساليب الخطابية ، فهي تحتاج إلى عزيمة وحزم أكثر مما تحتاج إلى استذكار وحفظ ، فاعمدوا إلى العمل أيها المتبايعون"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0007.png"}, {"n": 8, "paras": ["وَأَنَّ هَذَا صِرَاطِي مُسْتَقِيمًا فَاتَّبِعُوهُ وَلَا تَتَّبِعُوا السُّبُلَ فَتَفَرَّقَ بِكُمْ عَنْ سَبِيلِهِ ذَلِكُمْ وَصَّاكُمْ بِهِ لَعَلَّكُمْ تَتَّقُونَ .", "فان المسلمين في مشارق الأرض ومغاربها يترقبون كفاحكم ، ورسول الله يبارك جهادكم ، وربنا لن يضيع أجركم فلا تقفوا عند حد الكلام ، ولكن اعملوا ( والله معكم ولن يتركم أعمالكم ) .", "ووصية الله إليكم أن تستقيموا على طريقه . ولا تنحرفوا فتضلوا . ولا تنازعوا فتفشلوا ولا تتبعوا طرائق الشيطان فتصرفكم عن طريق الرضوان . واسألوا الله أن يوثق رابطتنا، ويديم ودنا ويهدينا سبلنا .", "أيها الاخوة : إن رسولنا صلوات الله تعالى عليه وسلم يبصرنا بطريقنا وما حولها في حديث كريم فيقول : ( ضرب الله مثلا"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0008.png"}, {"n": 9, "paras": ["اما غير هؤلاء فلهم دروس ومحاضرات ، وكتب ومقالات، ومظاهر وإداريات ، ولكل وجهة هو موليها فاستبقوا الخيرات . وكلا وعد الله الحسنى والسلام عليكم ورحمة الله وبركاته .", "صراطاً مستقيما وعلى جنبتي الصراط سوران فيهما أبواب مفتحة وعلى الأبواب ستور مرخاة وعلى باب الصراط داع يقول : يا أيها الناس ادخلوا الصراط جميعاً ولا تعوجوا وداع يدعو من فوق الصراط فاذا أراد الانسان أن يفتح شيئاً من تلك الأبواب قال ويحك لا تفتحه فانك إن تفتحه تلجه . فالصراط الاسلام، والسوران حدود الله ، والأبواب المفتحة محارم الله ، والداعي على باب الصراط كتاب الله ، وذلك الداعي الذي يدعو من فوق الصراط واعظ الله في قلب كل مسلم ) ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0009.png"}, {"n": 10, "paras": ["ايها الاخوان الصادقون . اركان بيعتنا عشرة فاحفظوها . « الفهم ، والاخلاص ، والعمل ، والجهاد ، والتضحية ، والطاعة ، والثبات ، والتجرد ، والاخوه ، والثقة » .", "ايها الأخ الصادق . إنما اريد بالفهم . ان توقن بأن فكرتنا اسلامية صميمة ، وان تفهم", "أيها الاخوة المجاهدون : الآن عرفتم دوركم وعليكم ان تعذروا غيركم ، فمن الناس من يقنع في صلته بالاسلام بالدروس والمحاضرات . او يكتفي بقراءة الكتب ومطالعة المقالات . او لا يستطيع ان يعمل إلا في نطاق المظاهر والشكليات ، فلا تحقروا هؤلاء فهذا جهدهم . وهم مثابون على قدر عملهم فتسابقوا في الصالحات ، واطلبوا عند الله اعلى الدرجات « لا يستوي"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0010.png"}, {"n": 11, "paras": ["الاسلام كما نفهمه في حدود هذه الأصول العشرين الموجزة كل الايجاز .", "القاعدون من المؤمنين غير أولي الضرر والمجاهدون في سبيل الله بأموالهم وانفسهم فضل الله المجاهدين بأموالهم وانفسهم على القاعدين درجة وكلا وعد الله الحسنى ، وسلام على إمامنا في الصادقين ، وسلام عليه في المجاهدين وسلام عليه مع النبيين ورحمة الله وبركاته .", "قلنا ان هذه الرسالة من قائد الدعوة الى الذين باعوا اموالهم وارواحهم في سبيل اسعاد الناس بنور ربهم وهؤلاء هم الذين اعتبرهم الله « إنما المؤمنون الذين آمنوا بالله ورسوله ثم لم يرتابوا وجاهدوا بأموالهم وانفسهم في سبيل الله اولئك هم الصادقون » والبيعة لا بد ان تستوفي شروطها ، وتستكمل اركانها حتى يعطينا الله ثمنها .", "وسنشرع بعون الله في إيضاح كل ركن من الاركان العشرة على حدة"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0011.png"}, {"n": 12, "paras": ["(١) الاسلام نظام شامل يتناول مظاهر الحياة جميعاً فهو دولة ووطن او حكومة وامة ، وهو خلق", "وأوصيك يا أخي ان تحرص على الصدق مع الله في كل ركن من هذه الأركان", "ولكي تفهم الاسلام فهماً دقيقاً لا غلو فيه ولا تفريط ، وكافياً يفي بحاجات الانسانية جميعاً ، وسهلاً ليس فيه جمود الجامدين ولا تعقيد المتفلسفين . لكي تصل الى هذا الفهم الصافي الصحيح الذي نفهم تدبر معنا هذه الاصول العشرين .", "(١) الاسلام دواء ركبه العليم الخبير سبحانه من عناصر هي هذه التكاليف . من صلاة وصيام ، وحسن خلق وبذل المال والوقت والروح في سبيل إسعاد الناس جميعاً فان تعاطينا هذا الدواء كاملا أعطانا الله شفاء الصدور وعزة الدنيا ونعيم الآخرة وإن ضيعنا أو استغنينا عن بعض هذه التكاليف استحال الدواء إلى داء . فالظالم مثلا ينقلب عليه القرآن حسرة وخسرانا . والله تعالى يقول وَنُنَزِّلُ مِنَ الْقُرْآنِ مَا هُوَ شِفَاءٌ وَرَحْمَةٌ لِّلْمُؤْمِنِينَ"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0012.png"}, {"n": 13, "paras": ["وقوة او رحمة وعدالة ، وهو ثقافة وقانون او علم وقضاء", "ولا يزيد الظالمين إلا خساراً » والقرآن كذلك للذين يؤمنون به ويعملون بأمره هدى وشفاء ، والذين أعرضوا عنه في آذانهم وقر وهو عليهم عمي . ومن هنا يتحتم أن نؤمن بالاسلام كله ونعمل بالقرآن كله وإلا فلا إيمان . والله يرد أمثال هؤلاء المفرطين فيقول « ويقولون آمنا بالله وبالرسول وأطعنا ثم يتولى فريق منهم من بعد ذلك وما أولئك بالمؤمنين » . وشمول الاسلام هذا يجعله يفتي في كل الشئون الخاص منها والعام فهو دولة لأن الفرد وحده مهما صلح وسما فلن يسعد نفسه ولا غيره . وهو وطن لأن الدولة المبعثرة التي لا يضمها وطن واحد لا تقدر على شيء . وهو حكومة لأن الناس ليسوا سواء في الاستجابة لنداء الضمير بل أكثرهم يحتاج إلى من يحرسه ويحول بينه وبين الشر إن شرع فيه ومن هنا ورد : إن الله ليزع بالسلطان مالا يزع بالقرآن ، ولهذا كانت الحكومة ركنا من أركان الاسلام . وهو أمة لانه لا يقوم إلا بجمع الناس على"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0013.png"}, {"n": 14, "paras": ["وهو مادة وثروة أو كسب وغنى . وهو جهاد ودعوة", "مبادىء الحق والخير ، وهو خلق لان الدنيا لا تقوم إلا بالفضائل . وقوة لان الخير ان لم يحرسه أهله عدا عليه الباطل . وهو رحمة لان الجماعات فيها القوي والضعيف ولا يحيا الضعفاء إلا في ظلال رحمة الاقوياء . والى جانب الرحمة عدالة حتى لا تأخذنا رأفة بالظالمين . وهو ثقافة فقد خلقنا لنعمر الارض التي سخرت لنا وسخر معها ما في السماء ، وما يقدر على تسخير شيء من هذا إلا العلماء . وهو قانون لان الآراء قد تختلف والاهواء قد تضل فلابد من قانون ينزله الله ليحكم بين عباده . والعلم الذي يريده الله ليس قاصرا على أحكام الفقه ، وإنما كل ما ينفع الناس من طب وهندسة ونحوها . وهو قضاء لان القانون ان لم يقض به بصدق وأمانة فلا خير فيه . وهو مادة لان المعنويات وحدها لا تكفي لحياة الناس . وهو ثروة لانها قوام الحياة تقضي بها الرغائب وتجاب المطالب . وهو كسب لان الرهبانية والتعطل موت الأحياء . وهو غنى لان العزة لا تكون للمتسولين ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0014.png"}, {"n": 15, "paras": ["أو جيش وفكرة كما هو عقيدة صادقة وعبادة صحيحة سواء بسواء .", "وهو جهاد لانه نور وكثيرون يحبون أن يعيشوا في الظلام فلا بد أن يجاهدهم الاسلام حتى لا يطفئوا نوره . وهو دعوة لانه نداء من الله الى خلقه فلا بد أن يصلهم النداء . وهو جيش لان الجهاد بالكلام لا يغني والكفاح بالحجة والبرهان قلما يجدى . والناس إن ظلموا البرهان واعتسفوا فالحرب أجدى على الدنيا من السلم وهو فكرة لانه لا يكره أحدا على الدخول فيه وإنما يعرض عليهم عقائده وتكاليفه فمن شاء أخذ ومن شاء ترك . والعقيدة ما انعقد في القلب واستقر فيه من التصديق بالله وكلماته ورسالاته . والعبادة مظاهر عبوديتنا لله مولانا كالصلاة والصوم والحج والجهاد مثلا . حاولنا فيما تقدم أن نوجز مظاهر الحياة التي شملها الاسلام كل مظهر على حدة ولو فصلنا الحديث عن هذه الامور ومنزلتها"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0015.png"}, {"n": 16, "paras": ["( ٢ ) القرآن الكريم والسنة المطهرة مرجعة كل مسلم في تعرف احكام الاسلام . ويفهم القرآن طبقا لقواعد اللغة العربية من غير تكلف ولا تعسف ويرجع في فهم السنة المطهرة الى رجال الحديث الثقات", "من الاسلام اطال بنا الحديث ولكن حسبنا هذه الاشارات . وعلى الجملة فالاسلام يتدخل في كل الشئون فهو يهتم بالفرد كما يهتم بالجماعة ويراقب الشعب كما يراقب الحكومة ويدعو إلى التسامح ويطالب بمكارم الاخلاق لكنه يؤدب المفسدين والظالمين . وهو يدخل المحكمة ويرافق القاضي ليقيم العدل بين الناس . ويريد منا مع هذا ان نحافظ على كياننا وندعو الناس إلى ديننا .", "( ٢ ) تكفل الله بحفظ الاسلام حتى يرث الارض ومن عليها . فالقرآن الكريم لم يبدل فيه قليل ولا كثير . وافعال الرسول (ص) واقواله وصلتنا كما هي بدون تحريف او تغيير وحتى"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0016.png"}, {"n": 17, "paras": ["( ٣ ) وللايمان الصادق ، والعبادة الصحيحة والمجاهدة نور وحلاوة يقذفها الله في قلب من شاء من عباده ، ولكن الالهام والخواطر والكشف والرؤى", "أعداء الاسلام لم يستطيعوا أن يطعنوا في هذين الأصلين . إذن يكفينا إن أردنا أن نحكم على شيء بأنه من الاسلام أو ليس منه يكفينا عندئذ ان نرجع إلى الكتاب الكريم او إرشادات النبي العظيم . والله تعالى يقول « فَإِن تَنَازَعْتُمْ فِي شَيْءٍ فَرُدُّوهُ إِلَى اللَّهِ وَالرَّسُولِ إِن كُنتُمْ تُؤْمِنُونَ بِاللَّهِ وَالْيَوْمِ الْآخِرِ » . ولا نتكلف في تفسير القرآن فنحمل اللفظ معنى غير موجود له في لغة العرب - ونعتبر الحديث إذا كان موجودا في الكتب الصحيحة كالبخاري ومسلم وغيرها .", "(٣) الايمان الصادق والعبادة الصحيحة يجزي الله بها في الدنيا قبل الآخرة فالأتقياء يلهمهم الله . والمجاهدون يهديهم ربهم . والله تعالى يقول : « يَأَيُّهَا الَّذِينَ آمَنُوا اتَّقُوا اللَّهَ وَآمِنُوا بِرَسُولِهِ يُؤْتِكُمْ كِفْلَيْنِ مِن رَّحْمَتِهِ وَيَجْعَل لَّكُمْ نُورًا تَمْشُونَ"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0017.png"}, {"n": 18, "paras": ["ليست من ادلة الأحكام الشرعية ولا تعتبر الا بشرط عدم اصطدامها بأحكام الدين ونصوصه .", "( ٤ ) والتمائم والرقي والودع والرمل والمعرفة والكهانة وادعاء معرفة الغيب وكل ما كان من هذا الباب منكر تجب محاربته الا ما كان آية من قرآن أو رقية مأثورة .", "به ، والنبي صلى الله عليه وسلم يقول « اتقوا فراسة المؤمن فانه ينظر بنور الله » لكن هذا النور ليس معناه أن نعتبر أي إلهام أو رؤيا إلا إذا اتفقت مع احكام الدين .", "(٤) الاحجبة ورقية عاشوراء والودع والرمل والفنجال والمندل وأوراق اللعب ( الكتشينة ) وكل ما شابهها منكر يجب أن نحاربه في كل مكان ولكنا نعلم ان النبي عليه الصلاة والسلام كان يرقي برقي منها : « أذهب البأس رب الناس اشف أنت الشافي لا شفاء إلا شفاؤك شفاء لا يغادر سقما » ومنها : « بسم الله أرقيك »"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0018.png"}, {"n": 19, "paras": ["( ٥ ) ورأى الامام ونائبه فيما لا نص فيه ، وفيما يحتمل وجوها عدة ، وفي المصالح المرسلة معمول به ما لم يصطدم بقاعدة شرعية . وقد يتغير بحسب الظروف والعرف والعادات - والأصل في العبادات التعبد", "والله يَشْفِيكَ مِن كُلِّ دَاءٍ يُؤْذِيكَ مِن شَرِّ النَّفَّاثَاتِ فِي العُقَدِ وَمِن شَرِّ حَاسِدٍ إِذَا حَسَدَ » . ومنها قراءة الفاتحة فهذه هي الجائزة وما عداها لا أصل له في الدين .", "( ٥ ) كل جماعة مؤمنة اختارت رجلا يلي أمرها يعتبر إماماً لها ورأى هذا الامام او من ينوب عنه يجب العمل به مادام لم يخرج عن حدود الاسلام ، فلقائد الجماعة الاسلامية مثلا ان يزيد نسبة الزكاة لانها تحتمل وجوهاً عديدة ، وكذا له ان يبيح ذبح الحيوان مثلا في بعض الايام إذا خاف القضاء عليه لو ذبح منه في كل يوم ، وله كذلك ان يلزم بتسجيل عقود البيع والايجار والزواج لان هذه النواحي تسمى المصالح المرسلة وطاعة الامام فيها"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0019.png"}, {"n": 20, "paras": ["دون الالتفات إلى المعاني ، وفي العاديات الالتفات إلى الأسرار والحكم والمقاصد .", "( ٦ ) وكل أحد يؤخذ من كلامه ويترك إلا المعصوم صلى الله عليه وسلم وكل ما جاء عن السلف واجبة وإن غير رأيه لتغير الظروف . والعبادات نفعلها كما هي دون ان نفتش عن اسرارها او حكمها لان المقصود الاول منها العبودية لله ، ولا يليق بالعبد ان يناقش سيده فيما يكلفه به . أما الامور العادية كالأكل والشرب والملابس فحكم فيها عقلك وفكر في المقصود منها فما وافق الشرع فهو حلال وإن لم يفعله النبي ( ص ) كصنف من الفاكهة لم يكن على عهد الرسول او نوع من الملابس لم يلبس في عهده فهذه وأمثالها لا حرج منها .", "(٦) المعصوم من الخطأ هو النبي عليه الصلاة والسلام وحده فكل ما صدر عنه فهو حق اما ماسوى ذلك حتى وإن صدر عن الصحابة او التابعين . فان وافق القرآن والسنة قبلناه"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0020.png"}, {"n": 21, "paras": ["رضوان الله عليهم موافقاً للكتاب والسنة قبلناه وإلا فكتاب الله وسنة رسوله اولى بالاتباع ، ولكنا لا نعرض للأشخاص فيما اختلف فيه بطعن او تجريح ، ونكلهم إلى نياتهم . وقد افضوا إلى ما قدموا .", "( ٧ ) ولكل مسلم لم يبلغ درجة النظر في ادلة الاحكام الفرعية ان يتبع اماما من أئمة الدين ويحسن به مع هذا الاتباع ان يجتهد ما استطاع في تعرف ادلة امامه", "وإلا فالكتاب والسنة أولى بالاتباع .", "(٧) المسلم الذي لم يتعمق في دراسة الدين له ان يتبع إماماً من الأئمة الأربعة مثلا - لكن هذا ليس بواجب عليه . ويحسن ان يجتهد في معرفة دليل الحكم الذي يعلم وعليه ان يقبل كل فتوى مصحوبة بالدليل إذا اطمأن إلى صدق من افتاه وكفايته . وعلى أهل العلم منا ان يتحرروا ويتبحروا في علمهم حتى يمكنهم ان ينظروا في فروع الدين ويجتهدوا فيها ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0021.png"}, {"n": 22, "paras": ["وان يتقبل كل ارشاد مصحوب بالدليل متي صح عنده صدق من ارشده وكفايته ، وان يستكمل نقصه العلمي إن كان من اهل العلم حتى يبلغ درجة النظر .", "( ٨ ) والخلاف الفقهي في الفروع لا يكون سبباً للتفرق في الدين ، ولا يؤدي الى خصومة ولا بغضاء ولكل مجتهد اجره . ولا مانع من التحقيق العلمي النزيه في مسائل الخلاف في ظل الحب في الله ، والتعاون على الوصول الى الحقيقة من غير ان يجر ذلك الى المراء المذموم والتعصب .", "(٨) إذا اختلفت مذاهب المسلمين - وهو اختلاف ليس في أصول الدين طبعاً ، لكنه في الفروع - فلا يليق بهم ان يتفرقوا او يختصموا او يتباغضوا بسبب هذا الخلاف فالمجتهد له أجره . إن أصاب او اخطأ ، ولا مانع من المناقشة الهادئة على علم دون تعصب او حب للجدل ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0022.png"}, {"n": 23, "paras": ["( ٩ ) وكل مسألة لا ينبني عليها عمل فالخوض فيها من التكلف الذي نهينا عنه شرعا ومن ذلك كثرة التعريفات للاحكام التي تقع ، والخوض في معاني الآيات الكريمة التي لم يصل إليها العلم بعد ، والكلام في المفاضلة بين الاصحاب رضوان الله عليهم وما شجر بينهم من خلاف ولكل منهم فضل صحبته وجزاء نيته وفي التأويل مندوحة .", "(٩) المسائل التي لا ثمرة لها لا يجوز ان نتحدث فيها كالسؤال عن النملة التي كلمت سيدنا سليمان صلى الله عليه وسلم هل كانت ذكرا أم أنثى . ولا يليق بنا ان نتكلم فيما كان بين الصحابة من خلاف ولا نطعن ولا نجرح واحداً منهم فكلهم لهم فضل الصحبة وجزاء المجتهد ان اصاب فله أجران وان أخطأ فله أجر ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0023.png"}, {"n": 24, "paras": ["( ١٠ ) معرفة الله تبارك وتعالى وتوحيده وتنزيهه أسمى عقائد الاسلام . وآيات الصفات واحاديثها الصحيحة وما يلحق بذلك من التشابه نؤمن بها كما جاءت من غير تأويل ولا تعطيل ولا نتعرض لما جاء فيها من خلاف بين العلماء ويسعنا ما وسع رسول الله ( صلعم ) وأصحابه « والراسخون في العلم يقولون آمنا به كل من عند ربنا » .", "( ١٠ ) الايمان بوحدانية الله وأنه لا شريك له ومعرفة جلاله وقدرته وكماله أعلى عقائد الدين ، والآيات والأحاديث التي ذكرت فيها صفات الله عز وجل نؤمن بها كما هي ولا نخوض في تفسيرها فلسنا أوسع علماً من رسول الله صلى الله عليه وسلم وأصحابه والراسخين في العلم الذين كانوا يقولون ( آمنا به كل من عند ربنا ) ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0024.png"}, {"n": 25, "paras": ["(١١) وكل بدعة في دين الله لا اصل لها استحسنتها الناس بأهوائهم سواء بالزيادة فيه او بالنقص منه ضلالة تجب محاربتها والقضاء عليها بأفضل الوسائل التي لا تؤدى إلى ما هو شر منها .", "(١٢) والبدعة الاضافية والتركية والالتزام في العبادات المطلقة خلاف فقهي لكل فيه رأيه ولا بأس بتمحيص الحقيقية بالدليل والبرهان .", "(١١) كل ما اخترع وألصق بالدين يسمى بدعة إضافية ، فان حذفنا .. شيئا كانت البدعة التركية وكلاهما ضلال يجب مقاومته بالطريقة التي لا توقع المسلمين فيما هو شر منه .", "(١٢) التقيد بنوع من العبادات في وقت معين او شكل معين لم يرد عن رسول الله (ص) . كقراءة الفاتحة عشرين مرة مثلا عقب صلاة الصبح . او كقراءة قل هو أحد المعروفة (بالصمدية) الف مرة ومثل هذا مختلف فيه ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0025.png"}, {"n": 26, "paras": ["( ١٣ ) ومحبة الصالحين واحترامهم والثناء عليهم بما عرف من طيب أعمالهم قربة إلى الله تبارك وتعالى. والأولياء هم المذكورون في قوله تعالى : « الذين آمنوا وكانوا يتقون » والكرامة ثابتة لهم بشرائطها الشرعية مع", "وهذا ما سماه مرشدنا رضى الله تعالى عنه ( الالتزام في العبادات المطلقة ) .", "( ١٣ ) كلمة الأولياء معناها الاحباب . وحب أحباب الله من صميم الايمان ، وإنما يحب الله من عباده من أخلص النية ، واجتهد في العبادة ، وتجمل بالادب ، واحسن إلى الناس بالمال والقول والعمل هؤلاء هم اولياء الله . وإذا احب الله عبداً او ولياً من هؤلاء اجرى على يديه اموراً لا يقدر عليها غيره وهذا ما يعرف بالكرامة . لكن هذا الولي لم يصنع الكرامة من نفسه حتى نظن انه يقدر على شيء من دون الله او ينفع او يضر ، وهل تعتقد ان اعظم ولي يصل إلى درجة رسول الله صلى الله عليه وسلم ؟ طبعاً لا . ومع هذا فالنبي عليه الصلاة والسلام"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0026.png"}, {"n": 27, "paras": ["اعتقادهم رضوان الله عليهم لا يملكون لأنفسهم نفعاً ولا ضراً في حياتهم أو بعد مماتهم ، فضلا عن أن يهبوا شيئاً من ذلك لغيرهم .", "( ١٤ ) وزيارة القبور أيا كانت سنة مشروعة بالكيفية المأثورة ولكن الاستعانة بالمقبورين أيا كانوا ونداؤهم لذلك وطلب قضاء الحاجات منهم", "هو الذي انزل عليه « قل لا املك لنفسي نفعاً ولا ضراً » وطبعاً ما دام لا يملك لنفسه فلا يملك غيره ، فاذا كان هذا حال رسول الله صلى الله عليه وسلم فالاولياء إذن محال ان يملكوا لانفسهم أو غيرهم شيئاً من النفع أو الضرر .", "( ١٤ ) منع الاسلام في اول الامر زيارة القبور للرجال والنساء . ثم اذن النبي عليه الصلاة والسلام للرجال فقط ان يزوروا القبور حتى يتذكروا الموت وما بعده من حساب وثواب وعقاب فيتمسكوا بالحلال ويخافوا من الحرام . هذه هي الحكمة"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0027.png"}, {"n": 28, "paras": ["عن قرب او بعد والنذر لهم وتشييد القبور وسترها وإضاءتها والتمسح بها والحلف بغير الله وما يلحق", "في زيارة القبور لكن لم تكن في يوم معلوم او في وقت مخصوص. ولم يكن يجلس على ابوابها احد لقراءة القرآن او لتوزيع الفطائر والفواكه، ولم يسافر احد من المسلمين الاولين لزيارة قبر مخصوص فالاسلام نهى عن الرحلة لهذا الغرض وارد فقط بالرحلة لزيارة الحرم بمكة والمسجد النبوي بالمدينة والمسجد الاقصى بالقدس.", "وكانت طريقة النبي عليه الصلاة والسلام في زيارة القبور ان لا يجلس عندها او يتمسح بها او يقرأ لها وإنما كان يدعو للأموات بهذه الدعوات: ( السلام عليكم دار قوم مؤمنين انتم السابقون، وإنا إن شاء الله بكم لاحقون يرحم الله المستقدمين منكم والمستأخرين أنتم لنا فرط ونحن لكم تبع نسأل الله لنا ولكم العفو والعافية والمغفرة. اللهم لا تحرمنا اجرهم ولا تفتنا بعدهم واغفر لنا ولهم ) ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0028.png"}, {"n": 29, "paras": ["بذلك من المبتدعات تجب محاربتها . ولا نتأول لهذه الاعمال سداً للذريعة .", "(١٥) والدعاء إذا قرن بالتوسل إلى الله بأحد من خلقه خلاف فرعي في كيفية الدعاء وليس من مسائل العقيده", "اما طلب قضاء الحاجات من المقبورين او الاستعانة بهم . فذلك يخالف تعاليم الاسلام ( إذا سألت فاسأل الله وإذا استعنت فاستعن بالله ) . والنذر لهم والحلف بهم او بالآباء والامهات ونحو ذلك منهى عنه شرعاً . فالنذر لا يكون إلا لله - والنبي عليه الصلاة والسلام يقول : ( من كان حالفاً فليحلف بالله او ليدع ) - وتشييد القبور وإضاءتها وكسوتها كبائر تجب محاربتها حتى نغلق باب الفتنة .", "(١٥) إذا دعوت الله بحق حبه للنبي ( ص ) او لاتباعه رضوان الله عليهم فذلك هو التوسل وهو محل خلاف بين العلماء منهم من اجازه ومنهم من منعه والممنوع قطعاً دعاء غير الله ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0029.png"}, {"n": 30, "paras": ["( ١٦ ) والعرف الخاطيء لا يغير حقائق الالفاظ الشرعية بل يجب التأكد من حدود المعاني المقصودة بها والوقوف عندها كما يجب الاحتراز من الخداع اللفظي في كل نواحي الدنيا والدين فالعبرة بالمسميات لا بالأسماء .", "( ١٧ ) والعقيدة اساس العمل وعمل القلب أهم من", "( ١٦ ) يحاول بعض المفسدين أن يطلقوا على مفاسدهم التي يفعلونها أسماء مخترعة يريدون بها الهروب من حرمة هذه المفاسد . لكن هذه مخادعة لله وللمؤمنين فيجب ان نحترس من مثل هذا التمويه والعبرة بحقيقة الشيء لا بالاسم الذي يسمونه به فالحشيش مثلا يقول السفهاء انه يبسط ولا يخدر فليس من انواع الخمور والانبساط في نظر الشرع يساوى الاسكار تماماً .", "( ١٧ ) عرفنا ان العقيدة هي المعاني التي تمتلىء بها القلب وأساس الاسلام العقيدة الصادقة والعبادات تبنى على هذا الاساس"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0030.png"}, {"n": 31, "paras": ["عمل الجارحة وتحصيل الكمال في كليهما مطلوب شرعاً وإن اختلفت مرتبتا الطلب .", "( ١٨ ) والاسلام يحرر العقل ويحث على النظر في الكون ويرفع قدر العلم والعلماء ويرحب بالصالح النافع من كل شيء والحكمة ضالة المؤمن أنى وجدها فهو أحق الناس بها .", "وطبعاً لا يصلح بناء بدون أساس فمن أخاص في عقيدته كفاه العمل القليل وإن كان الأفضل ان يكمل عقيدته وعبادته معاً .", "( ١٨ ) الاسلام لا يحجر على تكفير الناس ابداً بل يحرضهم على التعقل والتدبر في كل ما حولهم من السموات وما فيها والأرض وما عليها ، وما بينهما وما تحت الثرى ( التراب ) وكلما علم الانسان سراً من اسرار الكون كلما زاد ايمانه بقوة الله وقدرته وإتقان صنعته فاشتد خوفه منه وهذا هو ما تشير اليه الآية الكريمة : ( إنما يخشى الله من عباده العلماء ) والعلم هنا ليس علماً أحكام الشريعة فقط وإنما كل علم ينفع في الدين او في الدنيا ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0031.png"}, {"n": 32, "paras": ["( ١٩ ) وقد يتناول كل من النظر الشرعي والنظر العقلي ما لا يدخل في دائرة الآخرة ولكنهما لن يختلفا في القطعي فلن تصطدم حقيقة علمية صحيحة بقاعدة شرعية ثابتة ويؤول الظني منهما ليتفق مع القطعي فان كانا ظنيين فالنظر الشرعي اولى بالاتباع حتى يثبت العقلي أو ينهار .", "وعلينا ان نأخذ العلم والحكمة ولا يعنينا من أي وعاء خرجت.", "(١٩) أحكام القرآن كلها صادقة لا تخطىء ولا تتغير ( لا تبديل لكلمات الله ) وربنا الذي نزل القرآن وهو سبحانه وتعالى الذي علم الانسان فمحال ان يتناقض العلم الصريح مع صريح القرآن . فالقرآن مثلا يقرر أن الله استأثر بعلم ما في الارحام فلن يصل العلم ابداً إلى معرفة ما في بطن الحامل - وبعض الامور أشار القرآن اليها ولم يصدر حكماً قاطعاً فيها فاذا اكتشفت حقيقة علمية في هذه الناحية أولنا القرآن ليتفق مع هذه المعلومات ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0032.png"}, {"n": 33, "paras": ["( ٢٠ ) لا نكفر مسلماً أقر بالشهادتين وعمل بمقتضاهما وأدى الفرائض برأي أو بمعصية . إلا إن أقر بكلمة الكفر ، أو أنكر معلوماً من الدين بالضرورة أو كذب صريح القرآن ، أو فسره على وجه لا تحتمله أساليب اللغة العربية بحال ، أو عمل عملاً لا يحتمل تأويلاً غير الكفر .", "فكروية الارض مثلا نظرية علمية والقرآن يحتملها ويحتمل غيرها ففي مرة يقول : ( والله جعل لكم الارض بساطا ) وأخرى يقول ( والارض بعد ذلك دحاها ) فان قطع العلم بأنها كروية فذلك لا يتنافى مع القرآن . و الحقيقة العلمية والحكم الشرعي القاطع لا يختلفان أبداً فمثلا يقول الله تعالى ( والقمر قدرناه منازل ) هذا حكم شرعي والعلم يقطع بأن القمر يتنقل من منزلة إلى منزلة ويتحول من هلال إلى مافوق حتى يصير بدراً .", "( ٢٠ ) مسألة الكفر ورمي الناس به خطيرة غاية الخطورة"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0033.png"}, {"n": 34, "paras": ["وإذا علم الاخ المسلم « دينه » في حدود هذه الاصول فقد عرف معنى هتافه دائماً « القرآن دستورنا والرسول قدوتنا » .", "واريد بالاخلاص : أن يقصد الاخ المسلم بقوله", "فينبغي ان لا تسرف في اتهام الناس بالخروج عن الملة . وقد اتفق أئمة المسلمين على بعض أمور من فعلها كان مرتداً وخارجاً عن الاسلام . كأن يقر بكلمة الكفر ، او ينكر ان الصلاة واجبة ، أو أن الزنا حلال ، او يكذب صريح القرآن ، او يتخذ الفاظه هزوا ولعبا ، او يسجد لغير الله مثلا . فاذا فهمنا هذه الامور العشرين ، ادركنا معنى الاسلام ووعينا معنى الهتاف الذي نهتف به (القرآن دستورنا، والرسول إمامنا) . الاخلاص : سئل رسول الله صلى الله عليه وسلم عن الرجل يقاتل شجاعة والرجل يقاتل حمية والرجل يقاتل ليرى مكانه ، فمن من هؤلاء في سبيل الله ؟ فقال عليه"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0034.png"}, {"n": 35, "paras": ["وعمله وجهاده كله وجه الله ، وابتغاء مرضاته ، وحسن مثوبته ، من غير نظر إلى مغنم او مظهر او جاه او لقب أو تقدم أو تأخر . وبذلك يكون جندى « فكرة وعقيدة » لا جندي غرض ومنفعة « قل ان صلاتي الصلاة والسلام : ( من قاتل لتكون كلمة الله هي العليا فهو في سبيل الله ) .", "الشيطان عدو الانسان ، فاذا رأى من الانسان ميلا إلى الخير او حباً للاستقامة وسوس له بالتطلع إلى ما حول هذه الأعمال من سمعة او منفعة ، فاذا رآه يتعاون مع أهل الخير زين له أن يكون ظاهراً فيهم ، وبغض اليه ان يعمل كواحد منهم ، فاحذر مداخل الشيطان فانه يأتي من بين أيدينا ومن خلفنا وعن ايماننا وعن شمائلنا ، إلا ان يتداركنا الله برحمته . كل عمل تعمله وكل أمر تقصده الله يعلمه ويراه ، ويطلع على ما في الصدور ، فأخلص نيتك لله ، وابتغ بعملك"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0035.png"}, {"n": 36, "paras": ["ونسكي ومحياي ومماتي لله رب العالمين لا شريك له وبذلك أمرت ، وبذلك يفهم الاخ المسلم معنى هتافه الدائم « الله غايتنا » ، « والله اكبر ولله الحمد » .", "وجه الله ، فان مخادعة الله هي أشنع الخطايا ، وإن رجلا قال يا رسول الله : إني أحب أن أقاتل في سبيل الله وأن يُرى مكاني ، فنزل قول الله سبحانه . « فمن كان يرجو لقاء ربه فليعمل عملا صالحاً ولا يشرك بعبادة ربه أحدا » فهذا هو الشرك الأصغر كما قيل . ولا تلتفت إلى تصدر المجالس أو تقدم الصفوف ، او تستثقل من إخوانك أمراً ، فانه لا يتحقق لك الايمان إلا بأن تخفض جناحك للمؤمنين . وإن من أوصاف أحباب الله « أذلة على المؤمنين أعزة على الكافرين » . وتذكر أنك كلما قلت ( الله غايتنا ) فانما تعاهد الله على أن تخلص له النية في القول والعمل . والعهد الذي نقطعه في الصلاة ونقرأه في كتاب الله « إن"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0036.png"}, {"n": 37, "paras": ["وأريد بالعمل : ثمرة العلم والاخلاص « وقل اعْمَلُوا فسيرى اللهُ عَمَلَكم ورسوله والمؤمنون وستردون الى عالم الغيب والشهادة فينبئكم بما كنتم تعملون » .", "صلاتي ونسكي ومحياي ومماتي لله رب العالمين لا شريك له وبذلك أمرت » . العمل : الفهم وحده لا يكفي ، والفهم والاخلاص يفتجان العمل ، والدنيا والآخرة لا تنال ما فيهما إلا بالعمل « مَن عَمِلَ صالحا من ذكر أو أنثى وهو مؤمن فلنحيينه حياة طيبة » هذا أجره في الدنيا « ولنجزينهم أجرهم بأحسن ما كانوا يعملون » هذا جزاؤه في الآخرة . المسلم خليفة الله في أرضه ، فهمته إذا ثقيلة ، وتبعاته شاقة ، لكنه مطالب بها معان عليها ، والله يفعل ما يريد . الطريق طويل المدى كثير التبعات ، يظنه الناس خيالا ، ونعتقد أنه حقيقة ولا يأس مع الايمان « إنه لا ييأس من"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0037.png"}, {"n": 38, "paras": ["ومراتب العمل المطلوبة من الاخ الصادق :", "( ١ ) اصلاح نفسه حتى يكون قوي الجسم", "رَوْحُ اللهِ إلا القومُ الكافرون، فاستعن بالله ولا تعجز، واصبر حتى يفتح الله، واثبت للشدائد والمحن، فسيجعل الله بعد عُسر يُسرا، واعمل فكل عمل مُدّخر لك أجره يوم تلقى الله، وابدأ بنفسك ثم بمن تعول، والمطلوب منك : —", "( ١ ) إصلاح نفسك وذلك بأن تكون : ( أ ) قوي الجسم حتى تنفع نفسك والناس، فالمؤمن القوي خير وأحب إلى الله من المؤمن الضعيف . ( ب ) حَسَنَ الخُلُق، فأنت امين الله على خلقه، فخالقهم بِخُلُقٍ حَسَنٍ يستجيبوا لك ويعينوك على امرك ( اكمل الناس إيماناً أحسنهم اخلاقا ) . ( ج ) مثقف الفكر، فلا خير في مخلص لا يعقل، ولا في عامل ضيق الفكر . والعقل أصل الدين، فثقف عقلك حتى تستنير وتنير للناس الطريق ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0038.png"}, {"n": 39, "paras": ["متين الخلق مثقف الفكر قادراً على الكسب، سليم", "( د ) قادراً على الكسب ، فأفضل الطعام ما أكلته من عمل يدك ، والمال عصب الدعوات وقيام الحياة به ، ولا خير في عبادة تقطعك عن الكسب وتلحقك بالمقعدين . فالله تعالى يقول « فاذا قضيت الصلاة فانتشروا في الارض وابتغوا من فضل الله ، وكلما ربحت مالا وانفقت منه على عيالك واهلك واخوانك زدت عند الله فضلا .", "( ه ) سليم العقيدة حتى تصح صلتك بالله ، وعندها يجعل الله لك نوراً تمشى به ويعلمك ما لم تكن تعلم ويصرف عنك وساوس الشيطان . ( إنه ليس له سلطان على الذين آمنوا وعلى ربهم يتوكلون ) .", "( و ) صحيح العبادة ، فالله تعالى طيب لا يقبل إلا طيباً وقد كتب الاحسان على كل شيء ، وكما انك لا تطيق طعاماً نقص ملحه فكذلك ولله المثل الاعلى لا يقبل الله العبادة الناقصة او الخاطئة ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0039.png"}, {"n": 40, "paras": ["العقيدة ، صحيح العبادة مجاهداً لنفسه حريصاً على وقته", "( ز ) مجاهداً لنفسك فهي اعدى اعدائك ، وإن غلبتها لم يغلبك شيء في هذه الدنيا، فلا الايذاء ينال منك ، ولا الاغراء يفتنك إذا كنت قوي الارادة .", "( ح ) حريصاً على وقتك، فالوقت هو الحياة، وانت مسئول بين يدي الله يوم القيامة عن عمرك فيم افنيته ؟ وعن شبابك فيم ابليته ؟ وعن فراغك كيف امضيته ؟ واغتنم كل وقت يمر بك واملأه بالعمل للدنيا او للآخرة .", "( ط ) منظما في كل امرك ، فقد بني الدين على النظام ، فصلاتنا وصيامنا وجهادنا كل ذلك يدربنا على النظام ، فانطبع به واجعله عنوانك في كل افعالك واحوالك . !", "( ي ) نافعاً لغيرك ، فذلك لب الايمان واليك حديث المصطفى عليه الصلاة والسلام ( احب الناس إلى الله انفعهم للناس ، واحب الاعمال إلى الله سرور تدخله على مسلم تكشف عنه كربه ، او تقضى عنه دينا ، او تطرد عنه جوعاً ، ولان"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0040.png"}, {"n": 41, "paras": ["منظما في شئونه ، نافعا لغيره . وذلك واجب كل اخ على حدته .", "( ٢ ) وتكوين بيت مسلم بأن يحمل أهله على امشى مع اخ حاجة احب إلى من ان اعتكف في مسجدي هذا ( يعني مسجد المدينة ) شهراً أو من مشى مع اخيه في حاجة ليقضيها له - قضيت او لم تقض - ثبت الله قدمه يوم تزل الاقدام ) . فاذا استوفيت هذه النواحي فقد انفذت اول مرتبة من مراقب العمل .", "(٢) تكوين البيت المسلم ، فأهلك أحق الناس بهدايتك وتربيتك ، وإن اصلحهم الله اعانوك في الدنيا ، وأثابك على تربيتهم في الآخرة . والنبي صلى الله عليه وسلم كان يقول : ( خيركم خيركم لأهله وانا خيركم لأهلي ) . وللوصول إلى تكوين هذا البيت يجب عليك ان تحسن اختيار الزوجة فلا تنظر لجمالها او حسبها او مالها وتنسى دينها ،"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0041.png"}, {"n": 42, "paras": ["احترام فكرته والمحافظة على آداب الاسلام في كل", "الأمة سوداء ذات دين أفضل ، والنبي عليه الصلاة والسلام يحذرك سوء العاقبة إن غفلت عن هذه الناحية فيقول ( لا تنكحوا النساء لأموالهن فعسى أموالهن أن تطغيهن، ولا تنكحوهن لجمالهن فعسى جمالهن أن يرديهن ، ولكن انكحوهن على الدين ) . وإياك أن تغتر بظاهر المرأة إذا نشأت في بيت فسق او معصية ، فان العرق دساس ، وهي في جمال شكلها وخبث أصلها كالشجرة التي تنبت وسط النجاسات تراها مخضرة ولونها جميل ، ولكن جذرها ضارب في الأذى والخبث، وهذا هو الذي يشير إليه قول النبي عليه الصلاة والسلام : ( إياكم وخضراء الدمن ، قيل : وما خضراء الدمن يارسول الله ؟ قال : المرأة الحسناء في المنبت السوء ) . يشبه الرسول المرأة جميلة الشكل خسيسة الأصل - كما قلنا - بالشجرة الجميلة التي يمتد جذرها في النجاسة .", "وعليك بعد هذا ان تعرفها حقها وواجبها ، فان لم تستطع"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0042.png"}, {"n": 43, "paras": ["مظاهر الحياة المنزلية ، وحسن اختيار الزوجة ، وتوقيفها على حقها وواجبها ، وحسن تربية الاولاد والخدم", "فأخرجها إلى من يعلمها ، والحكم الشرعي ان المرأة أن تخرج بدون إذن زوجها للعلم والاستفتاء ، والمرأة الجاهلة عدوة نفسها وزوجها ، فعلموا نساءكم آداب الاسلام وحقوق الازواج وادعوا بدعاء القرآن الكريم : « ربنا هب لنا من أزواجنا وذرياتنا قرة أعين واجعلنا للمتقين إماماً » .", "أولادك أمانة عندك ، والله سائلك عنها ، فراع حق الأمانة وعلمهم ما يجب عليهم لله وللناس ، وبناتك أدبهن ، وألزمهن بيوتهن ، واستر عورتهن ، فان لم تفعل فأنت محاسب على ذنوبهن . ولقد أوحى الله إلى موسى عليه السلام ( أيما بنت بلغت الثانية عشرة ثم اقترفت إثما فأثم ذلك على أبيها ) . والنبي عليه الصلاة والسلام يقول من حديث طويل : ( الرجل في بيته راع وهو مسئول عن رعيته ) . ويقول ( إن"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0043.png"}, {"n": 44, "paras": ["وتنشئتهم على مباديء الاسلام ، وذلك واجب كل أخ على جدته كذلك .", "الله سائل كل راع عما استرعاه حفيظ أم ضيع ؟ حتى يسأل الرجل عن اهل بيته .", "وليس معنى هذا ان تقسو على زوجتك او تؤذي عيالك ، وإنما جنبهم الحرام ومتعهم بكل ما تقدر عليه من الحلال بالانفاق عليهم والتلطف معهم ، وتذكر رقة الاسلام التي يشير اليها قول النبي عليه الصلاة والسلام : ( مداعبة الرجل اهله صدقة ) . والخدم احسن عشرتهم وتعهد اخلاقهم ، فلا تفرط حتى تضيع حقوق الله ، ولا تتشدد حتى تضيع حقوق الناس .", "وإصلاح النفس وتكوين البيت المسلم كلاهما مهمة فردية يجب على كل أخ ان يقوم بها ، وان يؤديها على اكمل وجوهها ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0044.png"}, {"n": 45, "paras": ["( ٣ ) وارشاد المجتمع بنشر دعوة الخير ومحاربة الرذائل والمنكرات . وتشجيع الفضائل ، والامر", "( ٣ ) بعد إصلاح الفرد والأسرة يبقى علينا إصلاح المجتمع ، وذلك بنشر دعوة الخير وتزيينها اليه ، وتبصرته بجوانب البر والهدى . ومحاربة الرذائل والمنكرات ، فالأمة التي تسكت عن المنكر تستحق عذاب الله . وإنما لعن الله بني إسرائيل لأنهم كانوا لا يتناهون عن منكر فعلوه ولقد اوحى الله إلى نبي من انبيائه : إني مهلك من امتك اربعين الفاً من خيارهم وستين الفاً من شرارهم ، قال : يا رب هؤلاء شرارهم فما بال خيارهم ؟ قال الله : سكتوا عن منكراتهم وأكلوهم وشاربوهم فأخذهم الله جميعاً .", "والله جعل امة الاسلام خير امة اخرجت للناس ، إذا امرت بالمعروف ونهت عن المنكر فان سكتوا عذب الله الصالحين والظالمين معاً ، اقرأ قوله تعالى : « واتقوا فتنة لا تصيبن الذين ظلموا منكم خاصة » ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0045.png"}, {"n": 46, "paras": ["بالمعروف ، والمبادرة الى فعل الخير ، وكسب الراي العام الى جانب الفكرة الاسلامية ، وصبغ مظاهر الحياة", "ولهذا يشبه النبي عليه الصلاة والسلام الحافظين لحدود الله بقوم ركبوا أعلى السفينة ، ويشبه المعاندين لله بقوم ركبوا أسفلها ، ويشبه ارتكابهم المنكر بأنه خرق للسفينة ، فان سكت الذين في اعلاها غرقوا جميعاً ، وإن منعوهم من بغيهم نجت السفينة ونجوا جميعاً ، وواجب علينا مع هذا ان نأمر بالمعروف ونصبر عليه فذلك واجبنا ومهمتنا ونحن الأمة التي عهد الله اليها بهذه المهمة الكريمة حيث يقول : « وَلْتَكُن مِّنكُمْ أُمَّةٌ يَدْعُونَ إِلَى الْخَيْرِ وَيَأْمُرُونَ بِالْمَعْرُوفِ » .", "وأحسن من الأمر بالمعروف والنهي عن المنكر باللسان فقط ان تكون قدوة طيبة صالحة تفر من الحرام وتنفذ تعاليم الاسلام والشاعر يقول : والفعل من قول الهداة أفصح إذا أرادوا مرة ان ينصحوا"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0046.png"}, {"n": 47, "paras": ["العامة بها دائما، وذلك واجب كل أخ على حدته « وواجب الجماعة كهيئة عاملة ».", "(٤) وتحرير الوطن بتخليصه من كل سلطان", "وعلينا أن نعظم شعائر ديننا ، ونعتز بها ، ونشيع في الناس تقديسها ، حتى نملأ الارض بنور الاسلام ، فنحن خلفاء الله في ارضه ، وعلينا ان نكره المفسدين ، فهم اعداء رب العالمين ، وهم يغضبون حبيبنا فلا بد ان نغضب لغضبه . وإرشاد المجتمع هذا واجب فردي وجماعي ؟ فعلينا ان نهتم به منفردين ومجتمعين", "(٤) : وتحرير الوطن واجب فرضه الله على العباد ، فالاسلام دين العزة ، والاستعمار استعباد ومذلة ، ولا يجتمع الايمان والذل في قلب ابدا ، والامة المستضعفة ذليلة في الدنيا ومعذبة في الآخره : « إن الذين توفّاهم الملائكة ظالمي انفسهم قالوا فيم كنتم ؟ قالوا كنّا مستضعفين في الارض ، قالوا الم تكن"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0047.png"}, {"n": 48, "paras": ["أجنبي غير اسلامي سياسي او اقتصادي او روحي .", "(٥) واصلاح الحكومة حتى تكون اسلامية", "أرض الله واسعة فهاجروا فيها فأولئك مأواهم جهنم وساءت مصيرا .", "وقد خلقنا الله أحراراً فلماذا نرضى بالعبودية او نذل لغير الله فان قتلنا دون أوطاننا فقد أجرنا على الله . والنبي عليه الصلاة والسلام يقول من حديث له (من قتيل دون وطنه فهو شهيد) . فواجب علينا أن نخلص وطننا من كل تحكم أجنبي غير اسلامي سواء كان تحكماً سياسياً او عسكرياً أو مالياً .", "( ٥ ) إذا صلح الفرد ، وصلحت الأسرة ، وصاح المجتمع ، وتحرر الوطن ، ولم تقم على رأس الأمة حكومة اسلامية تهدّم ما بنينا . والحاكم في الرخاء يجب أن يعيش كأوسط الناس ، وفي الشدة كأقلهم ، والحاكم أجير عند الامة وعمله ان يسعى لخيرها ويستميت في دفع الأذى عنها . ولا تعتبر الحكومة إسلامية إلا إذا أدى أعضاؤها فرائض الإسلام ، ولم يتجاهروا بالعصيان ، ونفذوا احكام القرآن ، فان"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0048.png"}, {"n": 49, "paras": ["بحق وبذلك تؤدي مهمتها كخادم للأمة وأجبر عندها وعامل على مصلحتها والحكومة الاسلامية ما كان أعضاؤها مسلمين مؤدين لفرائض الاسلام غير متجاهرين بعصيان وكانت منفذة لأحكام الاسلام وتعاليمه . ولا بأس بأن تستعين بغير المسلمين عند الضرورة", "احتاجت إلى خبراء او فنيين في نواح لا غنى للأمة عنها . فليس محرما أن تستعين بغير المسلمين بشرط ان لا يكون في المسلمين من يستطيع أداء هذه المهمة ، وان لا يولى الكافر القيادات العامة مهما كانت خبرته . وعلامات الحكومة الاسلامية ان تشعر بمسئوليتها عن كل فقير او مريض او أسير او جاهل او مظلوم في الأمة - بل هي مسئولة حتى عن الحيوان - ورئيس الحكومة الاسلامية في العصر الاسلامي الأول كان يقول ( والله لو عثرت بغلة بالعراق لخشيت أن أسأل أمام الله عنها لم لم أمهد لها الطريق؟). وقساة القلوب يحرمهم الله من الخير ، ولا يجرى على"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0049.png"}, {"n": 50, "paras": ["في غير مناصب الولاية العامة ولا عبرة بالشكل الذي تتخذه ولا بالنوع ما دام موافقاً لقواعد العامة في نظام الحكم الاسلامي، ومن صفاتها الشعور بالتبعة، والشفقة على الرعية، والعدالة بين الناس، والعفة عن المال العام والاقتصاد فيه.", "أيديهم للأمة أي نصر والنبي (ص) يقول ( شرار امرائكم الذين تكرهونهم ويكرهونكم وخيارهم الذين تحبونهم ويحبونكم وتدعون لهم ويدعون لكم ) أو كما قال.", "والعدل أساس الملك وهو واجب بين الاحباب والاعداء بل بين المسلمين وغير المسلمين وربنا يأمر بالعدل على كل حال فيقول «يأيها الذين آمنوا كونوا قوامين بالقسط شهداء لله ولو على أنفسكم أو الوالدين والاقربين»، ويقول : « يا أيها الذين آمنوا كونوا قوامين لله شهداء بالقسط ولا يجرمنكم شنآن قوم على أن لا تعدلوا . اعدلوا هو أقرب للتقوى» والقسط: الحق."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0050.png"}, {"n": 51, "paras": ["ومن واجباتها : صيانة الأمن ، وإنفاذ القانون ، ونشر التعليم وإعداد القوة وحفظ الصحة ، ورعاية المنافع العامة ، وتنمية الثروة وحراسة المال ، وتقوية الأخلاق ، ونشر", "والعدل - يجر منكم : يحملكم - شنآن : عداوة وبغض . والعفة عن أموال الدولة والاقتصاد فيها من أظهر علامات الحكومة الاسلامية فهذه الاموال أمانة والله لا يحب الخائنين .", "علمنا أن صفات الحكومة الاسلامية شعور بالتبعة ، ورأفة بالرعية وعدل، بين الجميع ومراقبة لله في مال الدولة - وواجب الحكومة أن تصون الامن وتنفذ القانون ، وتنشر التعليم ، وتعد للوطن قوة من شبابه الفتي المخلص النقي ، وعتاداً وسلاحاً يحمي به الارض والعرض ، وتحفظ الصحة وتسهر على المنافع العامة حتى لا يبقى في الامة فقير أو جاهل ، او مريض ، او متعطل لا عمل له او عامل لا يجد ما يعينه - وتنمية الثروة ، وحراسة مال الامة واجب مهم كذلك فالامة الفقيرة لا تقدر على شيء"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0051.png"}, {"n": 52, "paras": ["الدعوة ، ومن حقها متى أدت واجبها « الولاء والطاعة والمساعدة بالأنفس والاموال » .", "ولا تصلح لشيء . وتقوية الاخلاق فهي مفتاح السعادة . وإنما الامم الاخلاق ما بقيت فان هموا ذهبت اخلاقهم ذهبوا حقاً فالأمة التي ينتشر فيها الفسق ، او يروج فيها النفاق ، او تكثر فيها الخيانات ، امة منحطة مهما زعمت لنفسها الصدارة والامتياز .", "وواجب فوق هذه الواجبات جميعاً هو نشر دعوة الاسلام. فهو شكر لله على نعمة السلطان ، والقرآن الكريم يشير إلى هذا -- ويجعله سببا لنزول نصر الله على الحكام والعاملين للاسلام -- بقوله: «ولينصرن الله من ينصره إن الله قوي عزيز، الذين إن مكنناهم في الارض اقاموا الصلاة وآتوا الزكاة وامروا بالمعروف ونهوا عن المنكر ولله عاقبة الامور » ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0052.png"}, {"n": 53, "paras": ["فاذا قصرت : « فالنصح والارشاد ثم الخلع والابعاد ولا طاعة لمخلوق في معصية الخالق .", "( ٦ ) واعادة الكيان الدولي للامة الاسلامية", "فان ادت الحكومة هذه الواجبات فهم اولوا الامر الذين امرنا بطاعتهم ، وحبهم ومساعدتهم ، بالدماء والاموال .", "فاذا قصرت فالله يأمرنا اولا بالنصح والارشاد . والنبي عليه الصلاة والسلام يقول : ( الدين النصيحة قلنا لمن يارسول الله ؟ قال لله ولرسوله ولكتابه ولائمة المسلمين وعامتهم ) والنصيحة للحكام واجبة وإن كلفتنا الدماء والارواح كما يقول النبي (ص) : ( سيد الشهداء حمزة ورجل قام إلى إمام جائر فأمره ونهاده فقتله ) بل هذا يعد افضل الجهاد كما جاء في الحديث : ( افضل الجهاد كلمة حق عند سلطان جائر ) فان لم ينفع النصح والارشاد وجب علينا الخلع والابعاد فانه لا طاعة لمخلوق في معصية الخالق.", "( ٦ ) إعادة الكيان الدولي للأمة الاسلامية بتحرير اوطانها"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0053.png"}, {"n": 54, "paras": ["بتحرير أوطانها ، واحياء مجدها ، وتقريب ثقافتها ، وجمع كلمتها المفقودة حتى يؤدي ذلك كله إلى « إعادة الخلافة المفقودة والوحدة المنشودة » .", "واجب من أقدس الواجبات لوطننا الكبير كل شبر أرض يذكر فيه اسم الله . ولست أدرى سوى الاسلام لى وطنا الشام فيه ووادي النيل سيان وكلما ذكر اسم الله في بلد عددت أرجاءه من اب أوطاني وتمزيق الدولة الاسلامية الكبرى إلى هذه الدويلات الصغيرة شر أريد بنا، و كيد دبر من أعدائنا . فان في اجتماعنا قوة ومنعة لنا. تأبى الرماح إذا اجتمعن تكسراً وإذا افترقن تكسرت آحادا ولا بد من تقريب الثقافات وتوحيد السياسات وجمع كلمة المسلمين في مشارق الأرض ومغاربها حتى يتم لنا إعادة وحدتنا ومجد خلافتنا ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0054.png"}, {"n": 55, "paras": ["( ٧ ) واستاذية العالم بنشر دعوة الاسلام في ربوعه حتى لا تكون فتنة ويكون الدين كله لله ويأبى الله إلا ان يتم نوره . وهذه المراتب الأربعة الاخيرة تجب على الجماعة متحدة وعلى كل أخ باعتباره عضواً في الجماعة وما اثقلها تبعات وما اعظمها مهمات يراها الناس خيالا ، ويراها الاخ المسلم حقيقة ولن نيأس أبداً . ولنا في الله اعظم الامل . والله غالب على أمره ولكن أكثر الناس لا يعلمون .", "(٧) نحن قد استحفظنا على كتاب الله فلا بد أن تنير الدنيا كلها بنور القرآن - وديننا دين ( القيمة ) أي الوصاية على هذه الدنيا القاصرة ، فغايتنا لا تقف عند حد إسعاد المسلمين ، ولكنها تمتد حتى تم هداية الناس أجمعين ، واسمع هذا أمراً صريحاً في القرآن العظيم : « وقاتلوهم حتى لا تكون فتنة ويكون الدين كله لله » . « ويأبى الله إلا أن يتم نوره » . وما ذلك على الله بعزيز » ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0055.png"}, {"n": 56, "paras": ["وأريد بالجهاد : الفريضة الماضية إلى يوم القيامة المقصودة بقول رسول الله صلى الله عليه وسلم : « مَن لَمْ يَغْزُ وَلَمْ يَنْوِ الْغَزْوَ مَاتَ مِيتَةً جَاهِلِيَّةً »", "الجهاد : هو الفريضة المكتوبة على المؤمنين جميعاً الأولين منهم والآخرين ، وليست مقصورة على الصحابة كما يظن بعض الجاهلين . والله الذي كتب علينا الصيام هو سبحانه الذي فرض علينا القتال بلهجة واحدة وفي سورة واحدة : « يأيها الذين آمنوا كتب عليكم الصيام . » . كتب عليكم القتال وهو كره لكم وعسى أن تكرهوا شيئاً وهو خير لكم وعسى أن تحبوا شيئاً وهو شر لكم والله يعلم وأنتم لا تعلمون » . والنبي عليه الصلاة والسلام يقول : « من مات ولم يغزو ولم تحدثه نفسه بالغزو فليمت إن شاء يهودياً أو نصرانياً » .", "واقل درجاته الانكار بالقلب ، وأعلاه القتل في سبيل"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0056.png"}, {"n": 57, "paras": ["وأول مراتبه إنكار القلب وأعلاها القتل في سبيل الله وبين ذلك جهاد اللسان، والقلم، وكلمة الحق عند السلطان الجائر، ولا تحيا الدعوة إلا بالجهاد وبقدر سمو الدعوة وسعة", "الله، وبين الدرجتين درجات منها : جهاد اللسان، والقلم، واليد وكلمة الحق عند السلطان الجائر . والإسلام لا يرضى بالجبان وإن حلف على الإيمان . وكتابنا الكريم يطرد الجبناء من حوزة المسلمين فيقول : « ويحلفون بالله إنهم لمنكم وما هم منكم ولكنهم قوم يفرقون . ( يخافون ) لو يجدون ملجأ أو مغارات أو مدخلاً لولوا اليه وهم يجمحون » . ولا يتركه الاسلام حتى يشهر به القرآن ويسجل عليه نقص رجولته، ويلحقه بالنساء كما حكي المخلفين، ثم دمغهم بقوله : « رضوا بأن يكونوا مع الخوالف » . وفي حديث ابن عبسة وقصة اسلام السدوس، إيضاح وبيان .", "ولا تحيا دعوة إلا بالجهاد . . وعلم بلا جاه كلام مضيع، وفكرة بدون جيش لا تلبث أن تزول . ( وبقدر سمو الفكرة"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0057.png"}, {"n": 58, "paras": ["افقها تكون عظمة الجهاد في سبيلها ، وضخامة الثمن الذي يطلب لتأييدها وجزالة الثواب للعاملين لها وَجَاهِدُوا فِي اللَّهِ حَقَّ جِهَادِهِ", "وقدسيتها ومنها تكون عظمة الجهاد في سبيلها ، وضخامة الثمن الذي يطلب لتأييدها ) فقل الذين قدموا من الاسلام بالركعات والدعوات :", "يا ويح الدين ممن بات يحسبه وقتاً يُصام وأوقات يصليها وإنما الدين إيمان وتضحية وعزة تنشر الدنيا وتطويها وذكرهم بآيات الله التي لا تفرق بين الصلاة والجهاد : « يأيها الذين آمنوا اركعوا واسجدوا واعبدوا ربكم وافعلوا الخير لعلكم تفلحون، وَجَاهِدُوا فِي اللَّهِ حَقَّ جِهَادِهِ هُوَ اجْتَبَاكُمْ » . الآية .", "أيها الأخ الصادق . بشرى لك إن كنت من المجاهدين والنصر مكتوب للصادقين حتى يقوم الناس لرب العالمين ؛ ونبيك عليه الصلاة والسلام هو الذي يسوق البشرى فيقول :"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0058.png"}, {"n": 59, "paras": ["وبذلك تعرف معنى هتافك الدائم : « الجهاد سبيلنا » واريد بالتضحية : بذل النفس والمال والوقت والحياة وكل شيء في سبيل الغاية ، وليس في الدنيا جهاد لا تضحية معه ولا تضيع في سبيل فكرتنا تضحية . وإنما هو الأجر الجزيل ، والثواب الجميل ، ومن « لا تزال طائفة من أمتي قائمين بالحق ، ظاهرين على أمر الله لا يضرهم من خالفهم حتى يأتي وعد الله » التضحية : من الناس من يقول آمنا بالله فاذا أوذى في الله جعل فتنة الناس كعذاب الله ، ويدعى حب الله ولا يبذل قليلا ولا كثيراً في سبيل الله ، هذا وأمثاله يحكم عليه القرآن بأنه فاسق أو منافق فليس بمؤمن على حال ، فان لكل شيء علامة ، ولكل قضية برهان ، ومن بخل على الله ببذل مال ، أو فراق عيال ، أو تنازل عن رتبة . فليس من أحباب الله أبداً ، والقرآن يضع حب الله ورسوله والجهاد في كفة وفي"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0059.png"}, {"n": 60, "paras": ["قعد عن التضحية معنا فهو آثم « إن الله اشترى من المؤمنين أنفسهم وأموالهم » « قل إن كان آباؤكم وأبناؤكم ، الآية » ذلك بأنهم لا يصيبهم ظمأ ولا", "الكفة الأخرى كل ما في الدنيا من متاع ، فمن رجحت عنده الأولى فهو من الصادقين ، ومن شغلته الثانية فهو من الفاسقين وهذا هو القرآن ينطق بالحق « قل إن كان آباؤكم وأبناؤكم وإخوانكم وأزواجكم وعشيرتكم وأموال اقترفتموها وتجارة تخشون كسادها ومساكن ترضونها أحب إليكم من الله ورسوله وجهاد في سبيله فتربصوا حتى يأتي الله بأمره والله لا يهدي القوم الفاسقين » .", "ولماذا يثقل على الناس ان يضحوا في سبيل الله مع أن هذه التضحية لن تضيع أبداً . « ذلك بأنهم لا يصيبهم ظمأ ولا نصب ولا مخمصة في سبيل الله ولا يطأون موطئاً يغيظ الكفار ولا ينالون من عدو نيلاً إلا كتب لهم به عمل صالح"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0060.png"}, {"n": 61, "paras": ["نصب « الآية « فان تطيعوا يؤتكم الله أجراً حسنا » ، وبذلك تعرف معنى هتافك الدائم :", "إن الله لا يضيع أجر المحسنين . ولا ينفقون نفقة صغيرة ولا كبيرة ولا يقطعون وادياً إلا كتب لهم ليجزيهم الله أحسن ما كانوا يعملون » .", "أيها الأخ الصادق : أنت تتاجر مع الله وتجارتك هذه رابحة فمهما بذلت من ثمن فلا تستكثره على الله أبداً ووازن إن أردت بين البضاعة والثمن تجد الفرق الكبير والربح الوفير ( إن الله اشترى من المؤمنين أنفسهم وأموالهم بأن لهم الجنة ) ولما نزلت هذه الآية قال الصادقون من المؤمنين : والله إنها لصفقة ( بيعة ) رابحة . أنفس هو خالقها وأموال هو رازقها ثم يعطينا عليها أجرا الجنة إنها لصفقة رابحة - فقل للجبناء ما قال الله لهم ( أينما تكونوا يدرككم الموت ولو كنتم في بروج مشيدة ) وقل للبخلاء الجشعين ( متاع الدنيا قليل والآخرة خير لمن اتقى) وقل للمشاعين : ( إذ أجل الله إذا جاء لا يؤخر ) حتى المكان الذي كتب الله ان"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0061.png"}, {"n": 62, "paras": ["( والموت في سبيل الله أسمى أمانينا ) وأريد بالطاعة : ( امتثال الامر، وانفاذه تواً في العسر واليسر والمنشط والمكره ) وذلك ان مراحل هذه الدعوة ثلاث : التعريف : بنشر الفكرة العامة بين الناس . ونظام الدعوة في هذا الطور نظام الجمعيات الادارية . ومهمتها العمل للخير العام . ووسيلتها الوعظ والارشاد تارة، واقامة تزهق الروح فيه لابد ان تمارق جسدها عنده ( قل لو كنتم في بيوتكم لبرز الذين كتب عليهم القتل إلى مضاجعهم ) فأفقوا ينفق الله عليكم ، وجاهدوا ينصركم الله ويعظم اجركم . الطاعة : للدعوة ادوار ثلاثة لابد ان تمر بها دورا بعد الآخر . الدور الأول : التعريف بنشر تعاليم الاسلام ومحاسنه بين الناس والدعوة في هذا الدور تأخذ نظام الجمعيات الادارية . ومهمتها"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0062.png"}, {"n": 63, "paras": ["المنشئات النافعة تارة أخرى ، إلى غير ذلك من الوسائل العملية وكل شعب الاخوان القائمة الآن تمثل هذا الطور من حياة الدعوة وينظمها ( القانون الأساسي ) . وتشرحها رسائل الاخوان وجريدتهم والدعوة في هذا الطور ( عامة ) . ويتصل بالجماعة في كل من أراد من الناس متى رغب في المساهمة في أعمالها ووعد بالمحافظة على البر، وفعل الخير، والخدمات العامة . وسبيلها الوعظ والارشاد ، وإقامة المنشئات النافعة كالمستوصفات ، والمدارس ، والمساجد إلى غير ذلك من الوسائل . والكل راغب في المساهمة في هذا البر وهذه الخدمات والاعمال . ان يتصل بالاخوان متى وعد ان يحافظ على مبادىء الاسلام . والطاعة التامة ليست لازمة في هذا الدور . والأهم منها احترام المبادىء العامة ، وعدم الخروج على النظام ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0063.png"}, {"n": 64, "paras": ["مبادئها، وليست الطاعة التامة لازمة في هذا الطور بقدر ما يلزم فيه احترام النظم والمبادىء العامة للجماعة التكوين : باستخلاص العناصر الصالحة لحمل أعباء الجهاد وضم بعضها إلى بعض ونظام الدعوة في هذا الطور صوفى بحت من الناحية الروحية وعسكري", "الدور الثاني : التكوين : باستخلاص العناصر الصالحة لحمل أعباء الجهاد وضم بعضها إلى بعض . والدعوة في هذا الدور تحتاج إلى صفاء كامل في الروح ، واستجابة سريعة لكل أمر لا معصية فيه ، وتنفيذه فورا في العسر واليسر فيما نحب ونكره وليس ذلك بدعا في الاسلام فقادتنا هم أولو الأمر منا والله أمرنا بطاعتهم بقوله سبحانه وتعالى (وأطيعوا الله وأطيعوا الرسول وأولى الأمر منكم) وقد بايع رسول الله صلى الله عليه وسلم الجند الأولين على السمع والطاعة فيما يحبون ويكرهون كما روى البخاري. فخذ من الصوفية في هذه الناحية ان لا تشك ولا تتحرج . وخذ من"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0064.png"}, {"n": 65, "paras": ["بحت من الناحية العملية وشعار هاتين الناحيتين دائماً ( أمر وطاعة ) من غير تردد ولا مراجعة ولا شك ولا حرج وتمثل الكتائب الاخوانية هذا الطور من حياة الدعوة وتنظمها رسالة المنهج سابقاً وهذه الرسالة الآن .", "العسكرية ان لا تتردد ولا تتراجع . تكن جنديا في الكتيبة . والأسر والكتائب الاخوانية هم هذا الصنف الذي يدخر ليكون درعاً للاسلام وحاملا لراية القرآن . وقد سبقت رسالة التعاليم هذه رسالة المنهج . وفيها تنظيم لهذا الصنف من الأخوان .", "ونظام الدعوة في هذا الدور خاص لا يدخل فيه إلا من استعد استعدادا حقيقيا لتحمل أعباء جهاد طويل المدى كثير التبعات . وأول علامات هذا الاستعداد الطاعة الكاملة ( فأولى لهم طاعة وقول معروف ) ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0065.png"}, {"n": 66, "paras": ["والدعوة فيه ( خاصة ) لا يتصل بها إلا من استعد استعداداً حقيقياً لتحمل أعباء جهاد طويل المدى كثير التبعات . وأولى بوادر هذا الاستعداد كمال الطاعة .", "التنفيذ : والدعوة في هذا الطور جهاد لا هوادة معه وعمل متواصل في سبيل الوصول إلى الغاية ، وامتحان وابتلاء لا يصبر عليها إلا الصادقون . ولا يكفل النجاح في هذا الطور إلا كمال الطاعة كذلك -", "والدور الثالث : التنفيذ وكله جهاد لا هوادة معه ، واستجابة لنداء الله لعباده المؤمنين : ( يا أيها الذين آمنوا قاتلوا الذين يلونكم من الكفار وليجدوا فيكم غلظة واعلموا ان الله مع المتقين ) والعمل في هذا الدور متواصل حتى نصل إلى الغاية والابتلاء والامتحان والاختبار من مستلزمات هذا الجهاد وهذا العمل"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0066.png"}, {"n": 67, "paras": ["وعلى هذا بايع الصف الأول من الاخوان المسلمين في يوم ٥ ربيع الاول سنة ١٣٥٩ ه", "وأنت بانضمامك إلى هذه الكتيبة ، وتقبلك لهذه الرسالة ، وتعهدك بهذه البيعة . تكون في الدور الثاني وبالقرب من الدور الثالث فقدر التبعة التي التزمتها ، واعد نفسك للوفاء بها ..", "وما يصبر على ذلك إلا الذين صدقوا ما عاهدوا الله عليه . والطاعة الكاملة ألزم ما يكون في مثل هذه الفترة .", "وأنت إذا أنفذت هذه التعاليم ، وانضمت إلى هذا الصف الصادق من الاخوان ، وعقدت مع الله عهداً وبيعة على العمل لهذا الدين فأنت تكون في دور التكوين وعلى أبواب التنفيذ فسل الله ان يعينك على امرك ، وان يربط على قلبك ويثبت قدمك ولا تبدل تبديلا ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0067.png"}, {"n": 68, "paras": ["وأريد بالثبات : أن يظل الاخ عاملاً مجاهداً في تبديل غايته مهما بعدت المدة ، وتطاولت السنوات والاعوام حتى يلقى الله على ذلك وقد فاز باحدى الحسنيين فاما الغاية ، وأما الشهادة في النهاية . ( من المؤمنين", "الثبات : قد يطول بنا أمد الجهاد . وقد تتوالى الاعوام ولا نشهد النصر ، فلا يحزنك هذا وحسبك أنك تعمل لحساب الله . ويكفيك أن تلقي الله متمسكا بالحق عملا للكتاب الكريم . فاما أن تفوز بالحسنيين النصر والشهادة . وأما أن تسعد باحداهما فتكون من الذين عند ربهم يرزقون فرحين بما آتاهم الله من فضله . وكذلك كانت الصفوة الاولى من جند النبي عليه الصلاة والسلام . وسجل الله لهم هذا الفضل في كتابه الكريم فقال ( من المؤمنين رجال صدقوا ما عاهدوا الله عليه فمنهم من قضى نحبه ومنهم من ينتظر وما بدلوا تبديلا ) وتذكر يا أخي أن الوقت جزء من العلاج ، وأن كل شيء"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0068.png"}, {"n": 69, "paras": ["رِجَالٌ صَدَقُوا مَا عَاهَدُوا اللَّهَ عَلَيْهِ فَمِنْهُمْ مَنْ قَضَى نَحْبَهُ وَمِنْهُمْ مَنْ يَنْتَظِرُ وَمَا بَدَّلُوا تَبْدِيلًا ) والوقت عندنا جزء من العلاج ، والطريق طويلة المدى بعيدة المراحل .", "عناد الله بمقدار ، ولكن امة أجل . ولن تسير الامور دائما وافقة لهوانا ، ان تسأل بين يدي الله لماذا لم تنتصر ، ولكن ستسأل بين يديه هل عملت أو لم تعمل ؟ على المرء أن يسعى إلى الخير جهده وليس عليه أن تتم المقاصد وافرض أن صرختنا في واد ، وان القوم ضلوا وعموا ، وجعلوا أصابعهم في آذانهم ، فهل هذا يثنينا عن العمل ؟ لقد ظن هذا طائفة من اتباع موسى عليه السلام ، فراحوا يثبطون العاملين ما دام العمل لن يصل بهم إلى ثمرة . ولكن المجاهدين ثبتوا على حالهم ، واحتسبوا ثوابهم عند ربهم ( وإذ قالت أمة منهم لم تعظون قوما الله مهلكهم أو معذبهم عذابا شديدا قالوا معذرة إلى ربكم ولعلهم يتقون ) . مهمتك أن تداوي الناس بالقرآن الشافي لما في الصدور ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0069.png"}, {"n": 70, "paras": ["كثيرة العقبات ولكنها وحدها التي تؤدي الى المقصود مع عظيم الاجر وجميل المثوبة . وذلك أن كل وسيلة من وسائلنا « الستة » تحتاج إلى أحسن الاعداد، وتحين الفرصة ، ودقة الانفاذ . وكل", "فهل يليق بالمعالج أن ينقطع عن المريض إذا اشتد وجعه ؟ لا : الأمر يحتاج الى بذل العناية والمثابرة والمصابرة . فاما أن يشفى الله هذا المسكين . وإما أن يأخذه بعد أن يرى منك تمام الغيرة والشفقة وبذل أقصى الجهود ولن يضيع أجرك عند الله أبداً . واعلم اننا نطلب عظيما فنريد إصلاح أسر ، وتربية أمم وتحرير شعوب مستذلة ، وتكوين امبراطورية بل نريد ما هو أعظم . نريد أن نهدي الخلق جميعاً إلى دين الله القويم : واذا كانت الأماني كباراً تعبت في مرادها الأجسام وكل واحدة من هذه العظائم تحتاج الى تمام الاستعداد وترقب الفرص، ودقة التنفيذ . وكل ذلك مرهون بوقته الذي قدره"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0070.png"}, {"n": 71, "paras": ["ذلك مرهون بوقته: « وَيَقُولُونَ مَتَىٰ هُوَ قُلْ عَسَىٰ أَن يَكُونَ قَرِيبًا » .", "الله: ( وَيَقُولُونَ مَتَىٰ هُوَ قُلْ عَسَىٰ أَن يَكُونَ قَرِيبًا ) . وما جاء نصر حتى لنبي من الانبياء إلا بعد صبر طويل ، وجهاد مرير يكاد يصل بجنوده إلى حافة اليأس . وتلك سنة الله في الذين خلوا من قبل: ( حَتَّىٰ إِذَا اسْتَيْأَسَ الرُّسُلُ وَظَنُّوا أَنَّهُمْ قَدْ كُذِبُوا جَاءَهُمْ نَصْرُنَا ) .", "ولقد ظن بعض الأولين أن النصر يأتي من أول جولة فأنبأهم ربهم بأنهم يطلبون بضاعة غالية هي الجنة . وثمنها أن يتوالى عليهم الاختبار وامتحان واصغ بقلبك إلى قوله سبحانه : « أَمْ حَسِبْتُمْ أَن تَدْخُلُوا الْجَنَّةَ وَلَمَّا يَأْتِكُم مَّثَلُ الَّذِينَ خَلَوْا مِن قَبْلِكُم مَّسَّتْهُمُ الْبَأْسَاءُ وَالضَّرَّاءُ وَزُلْزِلُوا حَتَّىٰ يَقُولَ الرَّسُولُ وَالَّذِينَ آمَنُوا مَعَهُ مَتَىٰ نَصْرُ اللَّهِ ۗ أَلَا إِنَّ نَصْرَ اللَّهِ قَرِيبٌ » ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0071.png"}, {"n": 72, "paras": ["وأريد بالتجرد : أن تتخلص لفكرتك من كل ما سواها من المبادىء والاشخاص، لأنها أسمى الفكر وأجمعها وأعلاها . « صبغة الله ومن أحسن من الله", "التجرد : الاسلام دين كامل جمع الله فيه كل الخير وكل الحق ( فماذا بعد الحق إلا الضلال ) . والنبي عليه الصلاة والسلام يقرر أن الله فتح لنا كل أبواب السعادة بهذه الرسالة الكريمة . فيقول عليه الصلاة والسلام : ( ما تركت من خير إلا وأمرتكم به وما تركت من شر إلا ونهيتكم عنه ( ومن هنا كان عليه الصلاة والسلام لا يرضى من مسلم أن يتطلع لفكرة غير فكرته، أو يتتلمذ على غير ملته رأى أن عمر بن الخطاب يوما وقد أمسك صحيفة من التوراة فغضب عليه الصلاة والسلام واحمر وجهه وقال ( لقد جئتكم بها بيضاء نقية والله لو كان موسى حيا ما وسعه إلا اتباعي ) . يا أخي : الله يغار على دينه فلا تلمس هدى خارج حدود إسلامك ( وإلا فلن تهتدى إداً أبدا . انسيت"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0072.png"}, {"n": 73, "paras": ["صبغة « قد كانت لكم أسوة حسنة في ابراهيم والذين معه إذ قالوا لقومهم إنا برءاء منكم ومما تعبدون من دون الله كفرنا بكم وبدا بيننا وبينكم العداوة والبغضاء أبدا حتى تؤمنوا بالله وحده » والناس عند قول ربك (من يهد الله فهو المهتد ومن يضلل فلن تجد له وليا مرشدا ) وهل تحفظ قول رسول الله صلى الله عليه وسلم في حديثه الطويل عن القرآن ( عصمة لمن تمسك به ونجاة لمن اتبعه . من التمس الهدى فيه هداه الله ، ومن التمس الهدى في غيره أضله الله ومن تركه من جبار قصمه الله ) وعليك بعد هذا أن تحب أحباب ربك وتتخلص من أعدائه ولنا في السابقين من رسل الله خير قدوة ( قد كانت لكم أسوة حسنة في ابراهيم والذين معه إذ قالوا لقومهم إنا برآء منكم ومما تعبدون من دون الله كفرنا بكم وبدا بيننا وبينكم العداوة والبغضاء أبدا حتى تؤمنوا بالله وحده ». ولم يرجع ابراهيم عليه السلام"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0073.png"}, {"n": 74, "paras": ["الاخ الصادق واحد من سبعة أصناف مسلم مجاهد ،", "عن قراره هذا حتى مع ابيه فما استغفر له اول الامر الا لميعادمن ابيه له توقع ابراهيم ان يكون من بعده ايمان : « فلما تبين له انه عدو لله تبرأ منه » .", "والناس امام الاسلام واحد من سبعة اصناف ولكل حكمه ومعاملته :", "١ - المسلم المجاهد : وهو اخ لك لا يتم إيمانك حتى تحبه ورسول الله يقسم على هذا فيقول له : ( والذي نفسي بيده لن تدخلوا الجنة حتى تؤمنوا ولن تؤمنوا حتى تحابوا ) وبدون هذا الحب لا نطمع في مغفرة من الله ولا ثواب . فان الاسلام يروي لنا ان رجلاً عبد الله وجاهد في سبيله ، ثم لقى ربه فما فاز بشيء . بل اشهد الله الملائكة على نقص ايمانه في حديثه القدسي ( هل والى في ولياً او عادى في عدواً ) والله يريده حباً ينتج تعاوناً على الحق ، وتساندأ في العسر واليسر ، ووفاء في الحياة وبعد الممات ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0074.png"}, {"n": 75, "paras": ["أو مسلم قاعد .", "فأحب الاعمال إلى الله سرور تدخله على مسلم تكشف عنه كربة ، أو تقضي عنه دينا ، أو تطرد عنه جوعاً ، وخطوات تخطوها مع أخيك في حاجة تريد قضاءها له خير عند الله من تعبدك في أفضل المساجد شهراً - ومن خلف غازياً في سبيل الله في أهله بخير فكأنما غزى . وحقه على الجماعة الاسلامية ان غرم - دون تقصير منه - أن يسدد بيت المال ماغرمه . فان مات فعباله وديونه أمانة وضمانة في أعناق إخوانه ، ومعلمنا الاول صلى الله عليه وسلم شرع هذا المبدأ فقال : ( أنا أولى بكل مؤمن من نفسه من ترك مالا فلورثته من بعده ، ومن ترك ديناً أو ضياعاً فالي وعليّ ) .", "٢ - المسلم القاعد : وهو بحكم الله لا يساوي المجاهد أبداً قال الله تعالى : « لا يَسْتَوِي الْقَاعِدُونَ مِنَ الْمُؤْمِنِينَ غَيْرُ أُولِي الضَّرَرِ وَالْمُجَاهِدُونَ فِي سَبِيلِ اللَّهِ بِأَمْوَالِهِمْ وَأَنْفُسِهِمْ فَضَّلَ"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0075.png"}, {"n": 76, "paras": ["الله المجاهدين بأموالهم وأنفسهم على القاعدين درجة وكلا وعد الله الحسنى، وفضل الله المجاهدين على القاعدين أجراً عظيماً، درجات منه ومغفرة ورحمة وكان الله غفوراً رحيماً. والجهاد إما ان يكون فرض كفاية . وذلك إذا استقلت دول الاسلام واعتزت فتخرج طائفة بقصد نشر الاسلام والدعوة اليه . وهذه القعود فيها ينزل بصاحبه عن درجات إخوانه المجاهدين .", "أما إذا اعتدى على أي أرض من بلاد الاسلام فالجهاد فرض عين ، والأمة كلها مطالبة بالتعبئة العامة . والله تعالى يعلنها صريحة في كتابه العظيم : « انفروا خفافاً وثقالاً وجاهدوا بأموالكم وأنفسكم في سبيل الله » ، والقعود في هذه الحالة فسق يحرم صاحبه من مزايا الايمان في حياته وبعد مماته . فهو في الدنيا مذموم من الله والناس ، فمرة ينفى القرآن عنه الايمان فيقول فيه وفي أشباهه : « ويحلفون بالله انهم لمنكم وما هم منكم ولكنهم قوم يفرقون » ، ومرة يوبخهم على جبنهم فيقول : -"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0076.png"}, {"n": 77, "paras": ["- « رضوا بأن يكونوا مع الخوالف » ، وهو الى جانب هذا محروم من ولاية المسلمين كما حكم الله على الذين تخلفوا عن الهجرة بقوله : « والذين امنوا ولم يهاجروا مالكم من ولايتهم من شيء حتى يهاجروا » . وعلمنا القرآن كذلك أن هذا من صفات المنافقين اللذين اختبر الله أشباههم من قبل بالجهاد والابتلاء فيه ليمتحن قلوبهم . قال عز وجل مخاطباً احبابه واصحاب نبيه : « وما اصابكم يوم التقى الجمعان فباذن الله وليعلم المؤمنين وليعلم اللذين نافقوا وقيل لهم تعالوا قاتلوا في سبيل الله او ادفعوا قالوا لو نعلم قتالاً لاتبعناكم هم للكفر يومئذ اقرب منهم للايمان » . والقاعدون يتوعدهم الله بالهلاك والمقت في الاولى والآخرة فيقول سبحانه وتعالى « الا تنفروا يعذبكم عذاباً اليماً ويستبدل قوماً غيركم ولا تضروه شيئاً » . ويقول في الآية الثانية « وان تتولوا يستبدل قوماً غيركم » ، وفي الثالثة : « فسوف يأتي الله بقوم يحبهم ويحبونه » ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0077.png"}, {"n": 78, "paras": ["او مسلم آثم", "فالقاعدون عن الجهاد بعد احتلال العدو لأراضي المسلمين تجب مقاطعتهم ومعاداتهم ، فليسوا أكرم من السابقين الأولين من أصحاب رسول الله الذين تخلفوا فحكم الله بهجرهم وقطيعتهم حتى فرق رسول الله ﷺ بينهم وبين زوجاتهم ولولا توبة قبلها الله منهم لظلوا مطرودين من رحاب الاسلام اقرأ قوله تعالى : « وعلى الثلاثة الذين خلفوا حتى إذا ضاقت عليهم الأرض بما رحبت وضاقت عليهم أنفسهم وظنوا أن لا ملجأ من الله إلا إليه ثم تاب عليهم » .", "فأما إن كان القعود لعذر ، أ كان الجهاد لنشر الدعوة ولم يكن لتحرير أوطان المسلمين ؛ فلا أثم على القاعدين إذا بذلوا ما في استطاعتهم ، وذلك ما يحكم به القرآن الكريم : « ليس على الضعفاء ولا على المرضى ولا على الذين لا يجدون ما ينفقون حرج إذا نصحوا لله ورسوله » .", "٣ - المسلم الآثم : من تعدى حدود الله وخالف أوامر"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0078.png"}, {"n": 79, "paras": ["= الاسلام فقد أغضب ربه . فان رضينا بما يغضب ربنا أو سكتنا عمن يغضبه ؛ حقت علينا جميعاً كلمة العذاب ، وحرمنا الخير والبركة ، وامتلأت حياتنا بالشر والفساد .", "والمسلم أخو المسلم ومن حق أخيك عليك ان تذكره إذا نسي ، وأن ترشده ، إذا ضلّ ، وان تنقذه إذا رأيته على حافة الهاوية ، فان ركب رأسه ، واستمرأ المعصية ؛ فخذ على يده حتى يفيء إلى أمر الله .", "المعصية داء « إن عالجنا المصابين به نجونا ونجوا جميعاً . فان غفلنا أو أهملنا استحال الداء إلى وباء وأفنى الأمة كلّها .", "ورسول الله صلى الله عليه وسلم يقول : ( مثل القائم في حدود الله والواقع فيها كمثل قوم استهموا في سفينة فكان بعضهم في أعلاها وبعضهم في اسفلها وكان الذين في اسفلها اذا أرادوا أن يشربوا مرّوا على من فوقهم فقالوا لو أنا خرقنا خرقا واستقينا منه ، وهم أحدهم أن يخرق خرقاً . فان أخذوا على يديه نجا ونجوا وان تركوه هلك وهلكوا ) او كما قال : من أجل ذلك اوجب الله علينا ان ننهى عن المنكر ، حتى نكون اهلا لحراسة="], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0079.png"}, {"n": 80, "paras": ["= الحق، وهداية الخلق، والخلافة عن الله في الأرض، وبهذا نكون خير امة اخرجت للناس . فان لم نفعل لحقتنا اللعنة والغضب كما لعن الذين من قبلنا من بني إسرائيل . والله يحكى لنا قصتهم حتى لا نقع فيما وقعوا فيه فيقول « لُعِنَ الَّذِينَ كَفَرُوا عَلَىٰ بَنِي إِسْرَائِيلَ عَلَىٰ لِسَانِ دَاوُودَ وَعِيسَى ابْنِ مَرْيَمَ ذَٰلِكَ بِمَا عَصَوْا وَكَانُوا يَعْتَدُونَ * كَانُوا لَا يَتَنَاهَوْنَ عَن مُّنكَرٍ فَعَلُوهُ » .", "وتغيير المنكر على درجات ثلاث تتفاوت قوة وضعفاً. والرسول عليه الصلاة والسلام يرتبها فيقول : ( من رأى منكم منكراً فليغيره بيده ، فان لم يستطع فبلسانه ، فان لم يستطع فبقلبه ، وذلك اضعف الايمان ) .", "وقد يظن بعض الناس ان التغيير بالقلب يكفي فيه ان تقول بينك وبين نفسك : اللهم ان هذا منكر لا يرضيك . لا يكفي هذا فأنت خليفة الله في ارضه فكيف ترضى بما يغضبه ؟ ان علماء المسلمين قالوا : علامة الانكار بالقلب - التي هي اضعف الايمان - ان لا تؤاكل صاحب المنكر، ولا تجالسه ، ولا ترد عليه السلام ="], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0080.png"}, {"n": 81, "paras": ["الا ان كان يستتر بمنكره ، وترجو بلينك معه ان تعينه على الشيطان وان تقرب من قلبه يستجيب لك .", "اما ان تستحي من التذكير بحق الله ، او تعظ ثم تخالط العاصي وترضي عنه ؛ فذلك بعد عن الاسلام والايمان . واسمعه حكما صريحاً من الله الحكيم العليم « لا تجدُ قوماً يؤمنون بالله واليوم الآخر يوادُّون منْ حادَّ الله ورسوله ولو كانوا آباءهم او ابناءهم او اخوانهم او عشيرتهم اولئك كتب في قلوبهم الايمان وايدهم بروح منه ويدخلهم جنات تجري من تحتها الانهار خالدين فيها رضي الله عنهم ورضوا عنه اولئك حزب الله الا ان حزب الله هم المفلحون » .", "وبنوا اسرائيل الذين لعنهم الله وقص علينا القرآن نبأهم ماسكتوا عن المنكر ، وانما انكروا بألسنتهم ثم رضوا عن اصحاب المنكر ، كما يروي لنا النبي عليه الصلاة والسلام خبرهم فيقول : ( كان الواحد منهم يلتقى اخاه وهو على المعصية فيقول له اتق الله ="], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0081.png"}, {"n": 82, "paras": ["= ودع ما تصنع ثم يلقاه من الغداة (١) وهو على حاله فلا يمنعه ذلك ان يكون أكيله وشريبه وجليسه ، فلما فعلوا ذلك ضرب الله قلوب بعضهم ببعض ثم تلا قوله تعالى : « لُعِنَ الَّذِينَ كَفَرُوا مِن بَنِي إِسْرَائِيلَ » .. الخ الآية » ثم قال : « والذي نفسي بيده لتأمرون بالمعروف ولتنهون عن المنكر ولتأخذن على يد الظالم ولتأطرنه (٢) على الحق أطرا (٣) ، أو ليضربن الله قلوب بعضكم ببعض ، ثم يدعوا خياركم فلا يستجاب لهم » فواجبنا إذن نأخذ على يد الظالم وأن نؤدب العاصي بهجره ومقاطعته على الاقل . قريباً كان أو بعيداً . والدأ أو مولوداً والامر في الزوجة أولى وأحق . ألم تر أن الله شرع لك في القرآن ثلاث درجات لتأديب الزوجة إذا خفت عليها الانحراف والعوج « واللاتي تخافون نشوزهن فعظوهن واهجروهن في المضاجع واضربوهن فان أطعنكم فلا تبغوا عليهن سبيلا » وإن أصرت على موقفها ، ولم يجد معها وعظ الزوج لها ، وهجرها =", "(١) اليوم الثاني (٢) تكرهونه (٣) اكراها"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0082.png"}, {"n": 83, "paras": ["= وضربها ، فليس على الزوج أن يرضى بهذا الانحراف . وإنما يتولى الامر حكمان يقضيان في هذا النزاع كما علمنا القرآن العظيم « وإن خفتم شقاق بينهما فابعثوا حكما من أهله وحكما من أهلها إن يريدا إصلاحاً يوفق الله بينهما » وإن تعذر التفاهم ، ولم يلتق الحكمان في رأي واحد فالفراق خير من عشرة لا تطيع الزوجة فيها زوجها « وإن يتفرقا يغن الله كلا من سعته » . وبعض العلماء رأى ان يكون حال الزوج من زوجته هكذا ان خاف عليها ارتكاب المعصية مهما كان نوعها .", "ويرى البعض الآخر ان يكون حاله منها مطابقاً للأمر النبوي الكريم : ( من رأى منكم منكراً فليغيره بيده فان لم يستطع فبلسانه فان لم يستطع فبقلبه وذلك اضعف الايمان ) . وقد علمنا دليل تغيير المنكر بالقلب الذي هو اضعف الايمان، وذلك كما قدمنا بالمقاطعة ، والهجر والمخاصمة ، فلا يعتبر متمسكاً بأضعف الايمان من يعلم من زوجته وكذا بنته وولده معصية الله ثم يداعبهم ، او يؤا كلهم ، او يرضى عنهم ( فان الله لا يرضى عن القوم ="], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0083.png"}, {"n": 84, "paras": ["أو ذمى .", "الفاسقين ) . ولا تنسى أن الرسول عليه الصلاة والسلام يحمل الرجل تبعات أخطاء أهل بيته جميعاً فيقول : ( كلكم راع وكلكم مسئول عن رعيته والرجل في بيته راع ومسئول عن رعيته . . الخ ) . ولقد اوحى الى موسى عليه السلام ( أيما بنت بلغت الثانية عشرة ثم اقترفت إثما فاثم ذلك على أبيها ) .", "٤ - الذمى : وهو اليهودي أو النصراني وهؤلاء لا حرج علينا أن نأكل من طعامهم ، وأن نتزوج من نسائهم . كما صرح بذلك القرآن الكريم : ( وطعام الذين أوتوا الكتاب حل لكم وطعامكم حل لهم ، والمحصنات من المؤمنات والمحصنات من الذين أوتوا الكتاب من قبلكم إذا آتيتموهن أجورهن ) . وشرط الزواج من اليهودية او النصرانية ان لا تكون من المشركات بالله ، وان لا يكون في آبائها مشرك بالله . ولعل الحكمة في إباحة زواج المسلم بالذمية انها قد يعجبها -"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0084.png"}, {"n": 85, "paras": ["خلق زوجها ومعاملته فتدخل في الاسلام ومن حق الزوج عليها ان تطيعه . فان عصت فأمامه طرق العلاج التي ذكرناها وهي الوعظ ، والهجر ، والضرب فان لم تفي الى طاعته فالطلاق واجب ..", "وحقوق الله اولى بالعناية والرعاية، وكل الذي ابيح لها مخالفة ربها وزوجها فيه ، مسألة العقيدة ، لأنها قلبية اما ماسوى ذلك من المخالفات فلا تغتفر لها ابداً ، وهل تظن ان الاسلام يقر عشرة تسرق فيها الزوجة من زوجها مثلا ، او تكشف عورتها لغيره ؟ لن يقول عاقل بهذا الرأي ابداً فان الاسلام يلعن الرجل الذي يرضى عن زوجة سيئة المسلك وصدق رسول الله القائل : (لعن الله الديوث قالوا فما الديوث يارسول الله ؟ قال الذي يعلم الخبيث في بيته ثم يسكت ) .", "وإتماما للفائدة نذكر ان ذرية المسلم من الذمية مسلمون . فان خاف على ذريته ان تتأثر عقيدتهم بعقيدة امهم فالتفريق واجب. وعلى الجملة فالذمية إذا لم يهاجموا نافي ديننا، ولم يخرجونا-"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0085.png"}, {"n": 86, "paras": ["أو معاهد .", "من اوطاننا ، ولم يتعاونوا مع اعدائنا . لهم علينا ان نبرهم ولا نعتدى عليهم . فان طعنوا في ديننا او تآمروا على إيذائنا ، او تعاونوا مع اعدائنا ، فدماؤهم مهدرة : وذلك حكم الله في آياته: (لا ينهاكم الله عن الذين لم يقاتلوكم في الدين ولم يخرجوكم من دياركم ان تبروهم وتقسطوا إليهم ان الله يحب المقسطين انما ينهاكم الله عن الذين قاتلوكم في الدين واخرجوكم من دياركم وظاهروا على اخراجكم ان تولوهم ومن يتولهم فأولئك هم الظالمون ) .", "ه - المعاهد : وهذا الصنف يجب علينا ان نوفي له بعهدنا مادام هو من جانبه لم ينقض شروط المعاهدة : ( فما استقاموا لكم فاستقيموا لهم ) فان حاولوا نقصها او انتقاصها او اعانوا علينا وتستروا بها. فلاعهد لهم ولا امان . وهذه الشروط التي ذكرنا نص عليها القرآن جميعاً . اقرأ قوله تعالى : ( إلا الذين عاهدتم من المشركين ثم لم ينقصوكم شيئاً ولم يظاهروا عليكم"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0086.png"}, {"n": 87, "paras": ["أو محايد .", "أحداً فأتموا اليهم عهدهم الى مدتهم ان الله يحب المتقين ) . ولتعلم ان مجرد تجريحهم لتعاليم ديننا يعفينا من التقيد معهم بشروط المعاهدة ، ويلزمنا ان نقطع رقاب قادتهم وزعمائهم . إسمع الى جزائهم في كتاب الله الكريم : ( وإن نكثوا أيمانهم من بعد عهدهم وطعنوا في دينكم فقاتلوا ائمة الكفر إنهم لا ايمان لهم لعلهم ينتهون ) . بل ان الاسلام يحرضنا على تقتيلهم جزاء خيانتهم ومكرهم فيقول : ( الا تقاتلون قوماً نكثوا ايمانهم وهموا باخراج الرسول وهم بدءوكم اول مرة اتخشونهم فالله أحق أن تخشوه إن كنتم مؤمنين ) . ثم يضمن القرآن لنا النصر عليهم ويؤكد هزيمتهم لبغيهم . فيقول ( قاتلوهم يعذبهم الله بأيديكم ويخزهم وينصركم عليهم ويشف صدور قوم مؤمنين ) .", "٦ - المحايد : وهو الذي ليس علينا وليس معنا وهذا يجب ان لا نتعرض له بأذى إلا إذا كان يخفي وراء مظهر الحياد عداوة"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0087.png"}, {"n": 88, "paras": ["أو محارب . ولكل حكمة في ميزان الاسلام ، وفي حدود", "وتامراً علينا وتجسساً لحساب أعدائنا ، وفي أمثال هؤلاء يقول الله عز وجل « فإن اعتزلوكم فلم يقاتلوكم وألقوا إليكم السلم فما جعل الله لكم عليهم سبيلا » هذا هو الصنف المخلص في حياده « ستجدون آخرين يريدون أن يأمنوكم ويأمنوا قومهم كلما ردوا إلى الفتنة أركسوا فيها فان لم يعتزلوكم ويلقوا إليكم السلم ويكفوا أيديهم فخذوهم واقتلوهم حيث ثقفتموهم وأولئكم جعلنا لكم عليهم سلطاناً مبيناً » .", "٨ - المحارب : وهو قسمان منتسب إلى الاسلام وغير منتسب .", "فالأول كل من اغتصب حقوق الناس أو ابتز أموالهم معتمداً على قوة السلاح أو مسلطاً من قبل سلطان جائر. فهذا ومن أعانه أو آواه يعدهم الاسلام محاربين وإن كانوا مسلمين . وقد أفرد لهم"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0088.png"}, {"n": 89, "paras": ["هذه الأقسام توزن الاشخاص والهيئات، ويكون الولاء", "الفقهاء بابا سموه باب الحرابة، أو المحاربين، أو قطاع الطريق، وجزاؤهم مذكور في قول الله عز وجل : « إنما جزاء الذين يحاربون الله ورسوله ويسعون في الأرض فساداً أن يقتلوا أو يصلبوا أو تقطع أيديهم وأرجلهم من خلاف أو ينفوا من الأرض ذلك لهم خزي في الدنيا ولهم في الآخرة عذاب عظيم ، إلا الذين تابوا من قبل أن تقدروا عليهم فاعلموا أن الله غفور رحيم » والمالكية يوجبون تنفيذ هذا الحد على كل من ارتكب هذه الجريمة وإن كانت امرأة . غاية الأمر أن المرأة تقتل من غير صلب، ولا تنفي - راجع الشرح الكبير في فقه المالكية باب الحرابة .", "والثاني : محارب غير منتسب للاسلام وهو كل مناوىء للاسلام بيده ولسانه، رجلا كان أو امرأة، فرداً كان او جماعة . والاسلام دين بر ومرحمة، ودين عقل وحرية ؛ فهو لا يكره"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0089.png"}, {"n": 90, "paras": ["أو العداء .", "الناس على اعتناقه ، ولا يرغمهم من الدخول فيه، بل يوصي بالبر والرحمة بالمخالفين له ما داموا لم يصدوا الناس عن سبيله .", "وللاسلام في الحرب آداب عالية لم تعرف الدنيا لها نظير، فهو لا يرضى بقتل الشيخ ولا طفل ولا امرأة، ولا يبيح أن نلحق مدبراً، أو نجهز على جريح ، أو نسي إلى أسير ، أو نحرق نخلا، أو نقطع شجراً ، أو نخرب عامراً إلا لضرورة .", "ومع هذه الرحمة فالاسلام ليس ديناً أبلة ، يسكت عن رءوس الفتنة إذا تظاهروا بالمودة وحقيقة أعمالهم تنطق بالكيد للاسلام وأهله ، وإنما يعد هؤلاء سواء كانوا من الرجال أو النساء محاربين لا حرمة لأموالهم ولا لدمائهم . وإليهم تشير الآية الكريمة التي ذكرناها من قبل : سَتَجِدُونَ آخَرِينَ يُرِيدُونَ أَن يَأْمَنُوكُمْ وَيَأْمَنُوا قَوْمَهُمْ كُلَّمَا رُدُّوا إِلَى الْفِتْنَةِ أُرْكِسُوا فِيهَا . . . الخ الآية » .", "وما دام الفرد - رجلا كان أو امرأة - أو الأمة، نابذونا العداء"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0090.png"}, {"n": 91, "paras": ["وأريد بالأخوة : أن ترتبط القلوب والأرواح برباط العقيدة والعقيدة أوثق الروابط وأغلاها ، والأخوة أخ", "فدماؤهم مهدرة ، يحق لنا أن نقتلهم حيث وجدناهم ، فرادى أو جماعات، في معسكراتهم أو خارجها، وأموالهم كذلك حل على أن نخرج خمسها لله لأنها غنيمة ، سواء أخذت عقب معركة أو بدون قتال .", "الأخوة : الناس جميعاً من أب واحد وأم واحدة فهم أخوة مهما اختلفت أجناسهم وتباعدت أوطانهم ، والأديان تريد ان تذكر الناس بهذه الحقيقية ، وأن تجمعهم على هذه الاخوة . والاسلام وهو خلاصة الاديان جميعاً يحرص اشد الحرص على أن يملأ قلوب اتباعه بالعطف على الناس جميعاً ومن هنا كان صاحب الرسالة يدعو لمن خالفه وعصاه، بل لمن تعدى عليه واذاه فيقول عليه الصلاة والسلام في دعائه « اللهم اهد قومي فانهم لا يعلمون » . إذا كان هذا حال الاسلام مع غير المؤمنين به فما ظنك بحاله مع جنده والمعتنقين له . إنه لا يعدهم إلا اخوة يؤمنون"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0091.png"}, {"n": 92, "paras": ["الايمان، والتفرق أخ الكفر، واول القوة قوة الوحدة، ولا وحدة بغير حب، واقل الحب سلامة الصدر، واعلاه", "برب واحد، ويتلمذون على نبي واحد، ويعيشون ويموتون لغرض واحد، هو إسعاد انفسهم واسعاد الناس جميعاً بنور الله « إنما المؤمنون أخوة » ثم يشرع لهم الاسلام ما يتمنى هذه الرابطة ويزكيها ويقويها ويجعل من كل عمل يثمر هذه الثمرة عبادة وقربة، واعتقد ان عبادات الاسلام لم تخل ابداً من تأكيد لهذه الروابط وتثبيت لها. فما الصلاة الا صلة روحية وقلبية بالله رب العالمين بطريقة معلومة، تختمها بتحية ربنا ونبينا والامن والسلام لعباد الله الصالحين اخواننا، وما الزكاة الا تمرين على القيام بحق الأخوة، وما الصيام إلا حرمان نستجيب به لربنا ونشعر بآلام المحرومين من اخواننا، وما الحج الا هجرة في سبيل الله نستكشف بها احوال اخواننا في الله .", "والاسلام يحيط الاخوة بسياج مكين يحميها ان تعبث بها نزوات النفس او نزعات الشيطان فاذا اغاظ اخ لأخيه في القول"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0092.png"}, {"n": 93, "paras": ["مرتبة الايثار « وَمَن يُوقَ شُحَّ نَفْسِهِ فَأُولَئِكَ هُمُ الْمُفْلِحُونَ » والاخ الصادق يري اخوانه اولي بنفسه من", "فالاسلام يسارع لهذه النفس الحرجة فيذهب قلقها بقوله العظيم « أَذِلَّةٍ عَلَى الْمُؤْمِنِينَ » ويذكر المعتدي بأن هذه جاهلية لا تليق بالمسلمين، فاذا تباعدت النفوس وافترق المختلفان فالاسلام يجعل خيرهما الذي يبدأ بالسلام ، فاذا مر يومان على هجر مسلم لأخيه فالاسلام يحرم عليه أن يهجره فوق ثلاث .", "ولكي ينفرنا الاسلام من التفرق ، قرن الايمان بالاخوة ، والكفر بالتفرق في القرآن العظيم، وحديث النبي الكريم، فاسمع إلى القرآن اولا يقص عليك نبأ جماعة من أصحاب رسول الله سعى بينهم يهودي فأوغر صدورهم، وفرق بين قلوبهم، فهموا أن يقتتلوا فعد هذا ردة إلى الكفر بعد الايمان « يَا أَيُّهَا الَّذِينَ آمَنُوا إِن تُطِيعُوا فَرِيقًا مِّنَ الَّذِينَ أُوتُوا الْكِتَابَ يَرُدُّوكُم بَعْدَ إِيمَانِكُمْ كَافِرِينَ وَكَيْفَ تَكْفُرُونَ وَأَنتُمْ تُتْلَىٰ عَلَيْكُمْ آيَاتُ اللَّهِ وَفِيكُمْ رَسُولُهُ وَمَن يَعْتَصِم بِاللَّهِ فَقَدْ هُدِيَ إِلَىٰ صِرَاطٍ مُّسْتَقِيمٍ »"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0093.png"}, {"n": 94, "paras": ["نفسه لانه إن لم يكن بهم فلن يكون بغيرهم ، وهم إن لم يكونوا به كانوا بغيره . وإنما يأكل الذئب من الغنم", "يا أيها الذين آمنوا اتقوا الله حق تقاته ولا تموتن إلا وأنتم مسلمون واعتصموا بحبل الله جميعاً ولا تفرقوا واذكروا نعمة الله عليكم إذ كنتم اعداء فألف بين قلوبكم فأصبحتم بنعمتة إخوانا وكنتم على شفا حفرة من النار فأنقذكم منها كذلك يبين الله لكم آياته لعلكم تهتدون ، . ولقد قال لهم رسول الله (ص) حين وجدهم على تشاحن وتقاتل ( أو ترجعون بعدي كفاراً يضرب بعضكم رقاب بعض ) ولا حياة لأمة ولا لجماعة ولا لأسرة متفرقة - وقصة الرجل وأولاده وحزمة العصي من ألطف ما يقال في هذا المعنى وآخر ماقيل فيها . تأبى الرماح إذا اجتمعن تكسراً وإذا افترقن تكسرت آحادا ولا بد من حب يستقر في القلوب فيحميها ، ويربط عليها"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0094.png"}, {"n": 95, "paras": ["القاصية « والمؤمن للمؤمن كالبنيان يشد بعضه بعضا » . « والمؤمنون والمؤمنات بعضهم أولياء بعض » وهكذا", "وأقل هذا الحب أن تسلم الصدور فلا تنطوي على غل ولا حقد ولا حسد . وبهذه السلامة يسلم للعبد دينه ، ويعظم عند الله أجره ، ولقد جاء عن رسول الله صلى الله عليه وسلم أنه كان يجلس يوماً مع أصحابه في المسجد فقال : ( يطلع عليكم من هذا الباب رجل من أهل الجنة ) . فاذا بالداخل صحابي مغمور ( غير مشهور ) وفي اليوم الثاني قال عليه الصلاة والسلام هذا القول فاذا بالداخل هو هذا الصحابي نفسه . وفي الثالث حدث ما كان في اليومين الماضيين . فعجب الصحابة لأمر هذا الرجل المبارك ، وأراد أحد الجالسين أن يعرف السر في امتياز هذا الرجل عليهم فعرض على صاحب هذه البشرى أن ينزل ضيفاً عليه ، فاستضافه ثلاث ليال لم يجد له فيها كثير صلاة ولا في أيامها كثير صيام ، فقال له حدثنا رسول الله من امرك بكذا وكذا فبم نات هذه هذه الدرجة ؟ فقال : ( إني أبيت وليس في قلبي غل لأحد )"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0095.png"}, {"n": 96, "paras": ["يجب أن نكون .", "ولا أفهم كيف يدعى مسلم سلامة صدره وهو إذا نصح شقت عليه النصيحة ، واذا قيل له اتق الله أخذته العزة بالإثم . وصية إليك أيها المسلم أن لا يتغير قلبك على من نصحك وأعلى الحب أن تقدم اخاك على نفسك . وتلك منزلة عالية لا ينالها إلا ذو حظ عظيم . نسأل الله ان يجعلنا من هؤلاء الملحين وآثر إخوانك على نفسك فأنك لا تستطيع ان تسعد بدونهم وهم مع الله فلن يضيرهم ان تتخلى عنهم . واحذر ان يوسوس لك الشيطان بمحاولة الاستغناء عنهم فان الرسول عليه الصلاة والسلام يقول : ( من فارق الجماعة قيد شَعْرَة فقد خلع ربقة الاسلام من عنقه ) وأظنك تحفظ قول رسول الله صلى الله عليه وسلم : ( المؤمن للمؤمن كالبنيان يشد بعضه بعضاً ) وقوله كذلك : ( مثل المؤمنين كمثل الجسد الواحد إذا اشتكى عينه اشتكى كله ، وإذا اشتكى رأسه اشتكى كله ) . وتذكر دائماً قول ربك الحكيم العليم : ( والمؤمنون"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0096.png"}, {"n": 97, "paras": ["وأريد بالثقة : اطمئنان الجندي إلى القائد في كفاءته وإخلاصه اطمئناناً عميقاً ينتج الحب والتقدير والاحترام والطاعة « فلا وربك لا يؤمنون حتى يحكموك فيما شجر بينهم ثم لا يجدوا في أنفسهم حرجاً مما قضيت ويسلموا تسليما » والقائد جزء من الدعوة ولا والمؤمنات بعضهم أولياء بعض ) فأحبب إخوانك يتحقق لك معنى الايمان .", "الثقة : ربى الاسلام أتباعه على احترام القيادة وتوقيرها ، وعدم التشكك في إخلاصها ، ومن هنا كان القائد الأول نبينا صلى الله عليه وسلم أولى بالمؤمنين من أنفسهم ، وجعل رفع الصوت عنده محبط للعمل . وعد القرآن الكريم من أوصاف المؤمنين: ( وإذا كانوا معه على أمر جامع لم يذهبوا حتى يستأذنوه إن الذين يستأذنونك أولئك الذين يؤمنون بالله ورسوله ) ويسلب الايمان عن كل متبرم بحكم القيادة أو متمرد على تعاليمها."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0097.png"}, {"n": 98, "paras": ["دعوة بغير قيادة، وعلى قدر الثقة المتبادلة بين القائد والجنود تكون قوة نظام الجماعة وإحكام خططها ونجاحها في الوصول إلى غايتها وتغلبها على ما يتعرضها من عقبات وصعاب «فَأَوْلَى لَهُمْ طَاعَةٌ وَقَوْلٌ مَعْرُوفٌ»", "ولقد جاء أن رجلاً كانت له مع آخر خصومة، فرفع أمره إلى رسول الله صلى الله عليه وسلم، فقضى عليه الصلاة والسلام بما أراه الله، فتذمر صاحب الشكوى، ولم يعجبه الحكم، وذهب يعرض الأمر من جديد على عمر بن الخطاب. فقال له عمر: انتظر حتى آتيك بالفتوى ودخل عمر إلى بيته، فأخذ سيفه، وخرج للرجل فقطع عنقه، وذهب بسيفه يقطر دماً إلى رسول الله صلى الله عليه وسلم. فهم رسول الله صلى الله عليه وسلم أن يلوم عمر لأنه قتل مؤمناً. فنزلت هذه الآية الكريمة تنفي عن الرجل الأيمان لأنه لم يقبل حكم رسول الله: (فَلَا وَرَبِّكَ لَا يُؤْمِنُونَ حَتَّىٰ يُحَكِّمُوكَ فِيمَا شَجَرَ بَيْنَهُمْ ثُمَّ لَا يَجِدُوا فِي أَنفُسِهِمْ حَرَجًا مِّمَّا قَضَيْتَ وَيُسَلِّمُوا تَسْلِيمًا) . وقد كتب علينا في الاسلام احترام القيادة"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0098.png"}, {"n": 99, "paras": ["وللقيادة في دعوة الاخوان حق الوالد بالرابطة القلبية والاستاذ بالافادة العلمية، والشيخ بالتربية الروحية، والقائد بحكم السياسة العامة للدعوة ودعوتنا تجمع هذه المعاني جميعاً. والثقة بالقيادة هي كل شيء في نجاح الدعوات", "والاستجابة لها مهما كانت شخصية القائد فيقول عليه الصلاة والسلام: «اسمعوا وأطيعوا وان تأمر عليكم عبد حبشي». ولا تصلح جماعة لا قيادة لها مهما كان عددها قليلاً. وبهذا أوصى الاسلام: «إذا كنتم ثلاثة فأمروا أحدكم» وجعلت طاعة القائد من طاعة الله ورسوله. وذلك أمر صريح في القرآن: (وأطيعوا الله وأطيعوا الرسول وأولي الأمر منكم) وكلما وثق القائد في جنوده، ووثقت الجنود في قائدها، كلما استحقوا التأييد والنصر، وهذا هو الأليق بحال المؤمنين. كما يقول القرآن الكريم: (فأولى لهم طاعة وقول معروف). والقيادة في دعوتنا - دعوة الاسلام - لها حق الوالد في الحب"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0099.png"}, {"n": 100, "paras": ["ولهذا يجب أن يسأل الأخ الصادق نفسه هذه الأسئلة ليتعرف مدي ثقته بقيادته .", "١ - هل تعرف إلى قائده من قبل ودرس ظروف", "والتقدير ، مقابل ما تبذله القيادة لجندها من رعاية وعطف ورحمة ولها كذلك حق المعلم من الاكرام والادب ، بما لها في أعناق الجنود من توجيه وتعليم . ولها ثالثا حق الشيخ من دعاء الله أن يرضى عنه وشكراً له بما أجرى الله على يديه من خير وهداية . ولها بعد ذلك حق القائد من السمع والطاعة في المنشط والمكره بحكم بيعتنا وارتباطنا بقيادتنا . ايها الأخ الذكي : بعد أن ذكرنا لك حقوق القيادة وعلمت أنها تملك منك القلب والجسد ، والروح والدم ، والمال والولد ، أفليق بك أن تضع هذا كله في يد لم تطمئن بعد إلى إخلاصها؟!", "(١) وليس يكفي مجرد المعرفة السطحية، بل لا بد من عشرة تنكشف معها خفايا النفوس ، وطوايا الصدور في حالتي الرضا"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0100.png"}, {"n": 101, "paras": ["حياته ؟", "٢ - هل اطمأن إلى كفايته وإخلاصه ؟", "والغضب ، والعسر واليسر ، وكذا دراسة لظروف القائد يتمكن معها من الاطمئنان على ميوله واتجاهاته - وإن الاسلام ليرسم لنا الطريق الصحيح لمعرفة الرجال والحكم لهم أو عليهم وفي قصة عمر بن الخطاب التي سنمر بها درس كامل في هذه الناحية .", "جاء رضي الله عنه رجل يزكي صاحبا له . فسأله عمر : هل جاورته في حضر ؟ قال : لا . قال : هل صاحبته في سفر ؟ قال : لا قال هل عاملته بالدينار والدرهم ؟ قال لا ، قال عمر أظنك رأيته في المسجد يتمتم فقلت هو من الصالحين . قال : نعم يا أمير المؤمنين قال : اذهب فأنت لا تعرفه .", "( ٢ ) ودراستك لظروف حياة قائدك ستطمئنك الى كفايته ، وتذلك على إخلاصه ، واعلم أن القيادة تكليف لا تشريف وحمل ثقيل يلقى على اكتاف المسؤولين وبهذه العقيدة ="], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0101.png"}, {"n": 102, "paras": ["= تقوى صلة الجندي بفائدة وعليها يتوقف نجاح العمل وبلوغ الأمل. والامير معان على مهمته مادام فيها مخلصاً ، وعليها غير حريص وإليك وصية من السابقين الاولين . جاء في الاثر : ( إنك إن أوتيتها عن مسألة وُكلت إليها - أي إن طلبت الامارة لنفسك وكلك الله إليها فحرمت من التوفيق - وإن أوتيتها عن غير مسألة أعنت عليها ) ولقد كان عمر بن الخطاب يراها مصيبة لا يصبر لها إلا المتقون .", "كلمه واحد من الناس مرة وقال : يا أمير المؤمنين هلا عهدت بالامر من بعدك إلى والدك ! فغضب ورد عليه معنفاً ( أخزاك الله ياعدو الله ، والله ما ابتغيت بها وجه الله ما حمدتها فأرغب فيها لأحد من أهل بيتي ، والله لقد أجهدت نفسي ، وحرمت أهلي وإن نجوت كفاراً لاوزر ولا أجر إني لسعيد بحسب آل الخطاب أن يحاسب منهم واحد ويسأل عن أمر المسلمين). بهذا كشف لنا أمير المؤمنين عن أعباء القيادة ، وخطر المسؤولية عنها في الدنيا والآخرة . ="], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0102.png"}, {"n": 103, "paras": ["٣ - هل هو مستعد لاعتبار الأوامر التي تصدر إليه من القيادة « في غير معصية طبعاً » قاطعة لا مجال فيها للجدل ولا للتردد ولا للانتقاض ولا للتحوير ، مع إبداء النصيحة ، والتنبيه إلى الصواب .", "٤ - هل هو مستعد لأن يفرض في نفسه الخطأ", "(٣) وقائد استراحت نفسك - بعد المعرفة والتمحيص والدراسة - إلى صدقه وكفايته وإخلاصه وخشيته من ربه ، هو أولى بك من نفسك ، وهو أمين على الاسلام الذي تعملان له ، وباب الاجتهاد في فروع الدين لا في اصوله مازال مفتوحاً كما تعلم، فهل تثق بعلمه ورأيه إذا افتاك بشيء او امرك بما تعلم خلافه في المسائل الفرعية ام ترى ان شهوة الجدل وآفة الشك والحرج سيغلبانك ؟ ان كنت هكذا فصحح جنديتك ، فانها إذن مريضة وإلا فأنت إن شاء الله من الصادقين .", "(٤) وقريب مما سبق ان تسأل نفسك عن مدى احترامك"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0103.png"}, {"n": 104, "paras": ["وفي القيادة الصواب اذا تعارض ما أمر به مع ما يعلم في المسائل الاجتماعية التي لم يرد فيها نص شرعي ؟ ه - هل هو مستعد لوضع ظروفه الحيوية تحت تصرف الدعوة ، وهل تملك القيادة في نظرة حق الترجيح بين مصلحته الخاصة ومصلحة الدعوة العامة ؟", "لأوامر قيادتك (في غير معصية طبعاً) هل هي عندك قابلة للتأويل والتحوير والانتقاص والتحريف، ام أنت مستريح لهذه الاوامر مستجيب لها ؟ لأنها من طاعة الله الذي يقول : « وأطيعوا الله وأطيعوا الرسول وأولي الأمر منكم » ، كما ان هذه الطاعة انت مأمور بها من رسول الله مهما كانت شخصية القائد وذلك قوله عليه الصلاة والسلام (اسمعوا واطيعوا ولو تأمر عليكم عبد حبشي ) .", "(٥) واخيراً هل انت تؤثر ما عند الله على ما في هذه الدنيا؟"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0104.png"}, {"n": 105, "paras": ["وبالاجابة على هذه الأمثلة وأشباهها يستطيع الاخ ان يطمئن على مدى صلته بالقائد، وثقته به، والقلوب بيد الله يصرفها كيف يشاء « لَوْ أَنفَقْتَ مَا فِي الْأَرْضِ جَمِيعًا مَّا أَلَّفْتَ بَيْنَ قُلُوبِهِمْ وَلَكِنَّ اللَّهَ أَلَّفَ بَيْنَهُمْ إِنَّهُ عَزِيزٌ حَكِيمٌ » .", "وهل انت بما في يد الله اوثق منك بما في يدك ؟ ان كنت هكذا فأنت من جنود الاسلام المخلصين ، وإلا فمن آثر الدنيا فان الجحيم هي المأوى ، والله غني عن العالمين ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0105.png"}, {"n": 106, "paras": ["أيها الأخ الصادق", "إن إيمانك بهذه البيعة يوجب عليك اداء هذه الواجبات حتى تكون لبنة قوية في البناء :", "١ ان يكون لي ورد يومى من كتاب الله تعالى لا يقل عن جزء ، واجتهد ان لا تختم في اكثر من شهر ولا في اقل من ثلاثة ايام .", "٢ ان تحسن تلاوة القرآن والاستماع اليه ، والتدبر في معانيه ، وان تدرس السيرة المطهرة ؛ وتاريخ السلف بقدر ما يتسع له وقتك، واقل ما يكفي في ذلك كتاب «حماة الاسلام» وان تكثر من القراءة من حديث رسول الله صلى عليه وسلم وان تحفظ اربعين حديثاً على الأقل . ولتكن الأربعين النووية وان تدرس في اصول العقائد ، ورسالة في فروع الفقه .", "٣ ان تبادر بالكشف الصحي العام ، وان تأخذ في علاج ما يكون بك، من امراض ، وتهتم باسباب القوة والوقاية الجسمانية وتبتعد عن اسباب الضعف الصحي ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0106.png"}, {"n": 107, "paras": ["٤ - ان تبتعد عن الاسراف في قهوة اللبن والشاي ونحوها من المشروبات المنبهة فلا تشربها إلا لضرورة ؛ وان تمتنع بتاتا عن التدخين .", "٥ - أن تعنى بالنظافة في كل شيء : في المسكن والملبس والمطعم ومحل العمل ، فقد بني الدين على النظافة .", "٦ - أن تكون صادق الكلمة فلا تكذب أبداً .", "٧ - أن تكون قوي الارادة فلا تتردد أبداً .", "٨ - أن تكون وفياً بالعهد والكلمة والوعد ، فلا تخلف مهما كانت الظروف .", "٩ - ان تكون شجاعاً عظيم الاحتمال ، وافضل الشجاعة الصراحة في الحق، وكتمان السر، والاعتراف بالخطأ، والانصاف من النفس ، وملكها عند الغضب .", "١٠ - أن تكون وقوراً تؤثر الجد دائما ، ولا يمنعك الوقار من المزح الصادق ، والضحك في تبسم .", "١١ - أن تكون شديد الحياء ، دقيق الشعور ، عظيم"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0107.png"}, {"n": 108, "paras": ["التأثر بالحسن والقبيح ، تسر للأول وتتألم للثاني ، وان تكون متواضعاً في غير ذلة ولا خنوع ولا ملق ، وان تتطلب أقل من مرتبتك لتصل اليها بحق .", "١٢ - ان تكون عادلاً صحيح الحكم في جميع الأحوال ، لا ينسيك الغضب الحسنات، ولا تغضى للرضا عن السيئات ، ولا تحمل الخصومة على نسيان الجميل ، وتقول الحق ولو على نفسك ، او على اقرب الناس اليك وإن كان مراً .", "١٣ - أن تكون عظيم النشاط مُدَرَّباً على الخدمات العامة تشعر بالسعادة والسرور ، إذا استطعت أن تقدم خدمة لغيرك من الناس . فتعود المريض ، وتساعد المحتاج ، وتحمل الضعيف وتواسي المنكوب ، ولو بالكلمة الطيبة ، وتبادر دائماً إلى الخيرات", "١٤ - أن تكون رحيم القلب ، كريماً سمحاً ، تعفو وتصفح وتلين وتحلم ، وترفق بالانسان والحيوان ، جميل المعاملة ، حسن السلوك مع الناس جميعاً ، محافظاً على الآداب الاسلامية"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0108.png"}, {"n": 109, "paras": ["الاجتماعية ، فترحم الصغير ، وتوقر الكبير ، وتفسح في المجلس ولا تتجسس ولا تغتاب ولا تصخب ، وتستأذن في الدخول والانصراف", "١٥ - أن يجيد القراءة والكتابة ، وأن تكثر المطالعة في رسائل الاخوان وجرائدهم ومجلاتهم ونحوها ، وأن تكون لنفسك مكتبة خاصة مهما كانت صغيرة ، وأن تتبحر في علمك وفنك إن كنت من أهل الاختصاص ، وأن تلم بالشئون الاسلامية العامة إلماماً يمكنك من تصورها والحكم عليها حكماً يتفق مع مقتضيات الفكرة .", "١٦ - أن تزاول عملاً اقتصادياً مهما كنت غنياً ، وأن تقدم على العمل الحر مهما كان ضئيلاً ، وأن تزج نفسك فيه مهما كانت مواهبك العلمية .", "١٧ - ألا تحرص على الوظيفة الحكومية ، وأن تعتبرها أضيق أبواب الرزق ، ولا ترفضها إذا أتيحت لك ، ولا تتخلى عنها إلا إن تعارضت تعارضاً تاماً مع واجبات الدعوة ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0109.png"}, {"n": 110, "paras": ["١٨ - أن تحرص كل الحرص على أداء حق مهنتك من حيث الاجابة والاتقان ، وعدم الغش وضبط الموعد .", "١٩ - أن تكون حسن التقاضي لحقك ، وأن تؤدي حقوق الناس كاملة غير منقوصة بدون طلب . ولا تماطل أبداً .", "٢٠ - أن تبتعد عن الميسر بكل أنواعه مهما كان المقصد من ورائها ، وتتجنب وسائل الكسب الحرام مهما كان وراءها من ربح عاجل .", "٢١ - أن تبتعد عن الربا في جميع المعاملات ، وأن تتطهر منه تماماً .", "٢٢ - أن تخدم الثروة الاسلامية العامة بتشجيع المصنوعات والمنشآت الاقتصادية الاسلامية ، وان تحرص على القرش فلا يقع في يد غير إسلامية مهما كانت الاحوال ، ولا تلبس ولا تأكل إلا من صنع وطنك الاسلامي .", "٢٣ - أن تشترك في الدعوة بجزء من مالك ، وأن تؤدى الزكاة الواجبة فيه ، وان تجعل منه حقاً معلوماً للسائل والمحروم مهما كان دخلك ضئيلا ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0110.png"}, {"n": 111, "paras": ["٢٤ - أن تدخر للطوارىء جزءاً من دخلك مهما قل ، وألا تتورط في الكماليات أبدا .", "٢٥ - ان تعمل ما استطعت على إحياء العادات الاسلامية وإمانة العادات الأعجمية في كل مظاهر الحياة . ومن ذلك التحية واللغة ، والتاريخ ، والزي ، والأثاث ، ومواعيد العمل والراحة والطعام والشراب ، والقدوم والانصراف ، والحزن والسرور ... الخ ؟ وأن تتحرى السنة المطهرة في كل ذلك .", "٢٦ - ان تقاطع المحاكم الأهلية وكل قضاء غير اسلامي ، والأندية والصحف، والجماعات والمدارس والهيئات ، التي تناهض فكرتك الاسلامية مقاطعة تامة .", "٢٧ - ان تديم مراقبة الله تبارك وتعالى ، وتذكر الآخرة وتعد لها، وتقطع مراحل السلوك إلى رضوان الله بهمة وعزيمة وتتقرب إليه سبحانه وتعالى بنوافل العبادة ، ومن ذلك صلاة الليل ، وصيام ثلاثة أيام من كل شهر على الأقل ، والاكثار من الذكر القلبي واللساني . وتحرى الدعاء المأثور على كل حال .", "٢٨ - ان تحسن الطهارة وأن تظل على وضوء في غالب الاحيان"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0111.png"}, {"n": 112, "paras": ["٢٩ - ان تحسن الصلاة وتواظب على ادائها في اوقاتها ، وتحرص على الجماعة والمسجد ما امكن ذلك .", "٣٠ - ان تصوم رمضان ، وتحج البيت إن استطعت إليه سبيلا . وتعمل على ذلك ان لم تكن مستطيعاً الآن ذلك .", "٣١ - ان تستصحب دائماً نية الجهاد وحب الشهادة ، وان تستعد لذلك ما وسعك الاستعداد .", "٣٢ - ان تجدد التوبة والاستغفار دائماً ، وان تتحرز من صغائر الآثام فضلا عن كبائرها ، وان تجعل لنفسك ساعة قبل النوم تحاسبها فيها على ما فعلت من خير او شر ، وان تحرص على الوقت فهو الحياة . فلا تصرف جزءاً منه في غير فائدة ، وان تتورع عن الشبهات حتى لا تقع في الحرام .", "٣٣ - ان تجاهد نفسك جهاداً عنيفاً ، حتى يسلس قيادها لك ، وان تغض طرفك ، وتضبط عاطفتك ، وتقاوم نوازع الغريزة في نفسك ، وتسمو بها دائماً إلى الحلال الطيب ، وتحول بينها وبين الحرام من ذلك أياً كان ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0112.png"}, {"n": 113, "paras": ["٣٤ - ان تتجنب الخمر ، والمسكر ، والمفتر ، وكل ماهو من هذا القبيل كل الاجتناب .", "٣٥ - ان تبتعد عن اقران السوء ، واصدقاء الفساد ؛ واماكن المعصية والاثم .", "٣٦ - ان تحارب اماكن اللهو فضلا عن أن تقربها ، وأن تبتعد عن مظاهر الترف والرخاوة جميعاً .", "٣٧ - ان تعرف اعضاء كتيبتك فرداً فرداً معرفة تامة وتعرفهم نفسك معرفة تامة كذلك ، وتؤدي حقوق أخوتهم كاملة من الحب والتقدير ، والمساعدة والاثار ، وان تحضر اجتماعاتهم ، فلا تتخلف عنها إلا بعذر قاهر، وتؤثرهم بمعاملتك دائماً", "٣٨ - ان تتخلى عن صلتك بأية هيئة او جماعة لايكون الاتصال بها في مصلحة فكرتك ، وبخاصة إذا امرت بذلك", "٣٩ - ان تعمل على نشر دعوتك في كل مكان ، وان تحيط القيادة علماً بكل ظروفك ، ولا تقدم على عمل يؤثر فيها تأثيراً جوهرياً الا باذن ، وان تكون دائم الاتصال الروحي بالعمل بها ، وان تعتبر نفسك دائماً جندياً في الثكنة تنتظر الأمر"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0113.png"}, {"n": 114, "paras": ["أيها الأخ الصادق", "هذا مجمل لدعوتك ، وبيان موجز لفكرتك ؛ وتستطيع ان تجمع هذه المبادىء في خمس كلمات : الله غايتنا ، والرسول قدوتنا ، والقرآن شريعتنا ؛ والجهاد سبيلنا والشهادة امنيتنا .", "وان تجمع مظاهرها في خمس كلمات اخرى : البساطة ، والتلاوة ، والصلاة ، والجندية ، والخلق .", "فخذ نفسك بشدة بهذه التعاليم ، وإلا ففي صفوف القاعدين متسع للكسالى والعابثين ، واعتقد انك إن عملت بها ، وجعلتها امل حياتك ، وغاية غاياتك ، كان جزاؤك العزة والنصر في الدنيا ، والخير والرضوان في الآخرة ، وانت منا ونحن منك ، وإن انصرفت عنها ، وقعدت عن العمل لها فلا صلة بيننا وبينك ، وإن تصدرت فينا المجالس وحملت افخم الألقاب، وظهرت بيننا بأكبر المظاهر ، وسيحاسبك الله على قعودك اشد الحساب ، فاختر لنفسك ، ونسأل الله لنا ولك الهداية والتوفيق ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0114.png"}, {"n": 115, "paras": ["﴿ يَأَيُّهَا الَّذِينَ آمَنُوا هَلْ أَدُلُّكُمْ عَلَى تِجَارَةٍ تُنجِيكُم مِّنْ عَذَابٍ أَلِيمٍ ﴾ .", "١ - تُؤْمِنُونَ بِاللَّهِ وَرَسُولِهِ .", "٢ - وَتُجَاهِدُونَ فِي سَبِيلِ اللَّهِ بِأَمْوَالِكُمْ وَأَنفُسِكُمْ ذَلِكُمْ خَيْرٌ لَّكُمْ إِن كُنتُمْ تَعْلَمُونَ .", "١ - يَغْفِرْ لَكُمْ ذُنُوبَكُمْ .", "٢ - وَيُدْخِلْكُمْ جَنَّاتٍ تَجْرِي مِن تَحْتِهَا الْأَنْهَارُ وَمَسَاكِنَ طَيِّبَةً فِي جَنَّاتِ عَدْنٍ ذَلِكَ الْفَوْزُ الْعَظِيمُ .", "٣ - وَأُخْرَى تُحِبُّونَهَا نَصْرٌ مِّنَ اللَّهِ .", "٤ - وَفَتْحٌ قَرِيبٌ وَبَشِّرِ الْمُؤْمِنِينَ . ﴿ يَأَيُّهَا الَّذِينَ آمَنُوا كُونُوا أَنصَارَ اللَّهِ كَمَا قَالَ عِيسَى ابْنُ مَرْيَمَ لِلْحَوَارِيِّينَ مَنْ أَنصَارِي إِلَى اللَّهِ قَالَ الْحَوَارِيُّونَ نَحْنُ أَنصَارُ اللَّهِ فَآمَنَت طَّائِفَةٌ مِّن بَنِي إِسْرَائِيلَ وَكَفَرَت طَّائِفَةٌ فَأَيَّدْنَا الَّذِينَ آمَنُوا عَلَى عَدُوِّهِمْ فَأَصْبَحُوا ظَاهِرِينَ ﴾ . والسلام عليكم ورحمة الله وبركاته ."], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0115.png"}, {"n": 116, "paras": ["شباب الناري الشبابي"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0116.png"}, {"n": 117, "paras": ["فهرست", "الصفحة | الموضوع | الصفحة | الموضوع --- | --- | --- | ---", "٣ | تمهيد | ٢٤ | البدع ضلالة", "٥ | المقدمة | ٢٥ | محبة الصالحين", "١١ | شمول الاسلام | ٢٦ | زيارة القبور", "١٥ | مصادر التشريع | ٢٧ | التوسل", "١٦ | الرؤى ليست من أدلة الاحكام | ٢٩ | العبرة بالمسميات", "١٧ | التمائم منكر | ٣٠ | الاسلام يحرر العقل", "١٨ | رأي الامام ونائبه فيما لا نص فيه | ٣١ | النظر العقلي والشرعي", "١٩ | المعصوم هو النبي وحده | ٣٢ | الكفر والايمان", "٢٠ | اتباع إمام من الأئمة | ٣٣ | الاخلاص", "٢١ | التحقيق العلمي النزيه | ٣٦ | ثمرة العلم والاخلاص", "٢٢ | التكلف الذي نهينا عنه | ٣٧ | إصلاح النفس", "٢٣ | المتشابه | ٤٠ | تكوين البيت المسلم | | ٤٤ | إرشاد المجتمع | | ٤٦ | تحرير الوطن"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0117.png"}, {"n": 118, "paras": ["الصفحة | الموضوع | الصفحة | الموضوع", "٤٧ | إصلاح الحكومة | ٧٤ | المسلم القاعد", "٥٢ | الامبراطورية الاسلامية | ٧٧ | المسلم الآثم", "٥٤ | استاذية العالم | ٨٣ | الذمي", "٥٥ | الجهاد | ٨٥ | المعاهد", "٥٨ | التضحية | ٨٦ | المحايد", "٦١ | التعريف | ٨٧ | المحارب", "٦٣ | التكوين | ٩٠ | الاخوة", "٦٥ | التنفيذ | ٩٦ | الثقة", "٦٧ | الثبات | ١٠٥ | واجبات البيعة", "٧١ | الاسلام يكفي وحده | ١١٣ | تلخيص الدعوة", "٧٣ | المسلم المجاهد"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0118.png"}, {"n": 119, "paras": ["شباب النادي الشبابي"], "img": "../../../_ocr-work/libocr/sharh-bay3a/pages/0119.png"}]};
